// A PROVED verdict makes no reachability claim. x = 4 * n at u32 is a multiple
// of 4 modulo 2^32, since 4 divides 2^32, so it is never 1, 2 or 3 and no run
// reaches the check. The interval analysis cannot see that and keeps x = [1,3]
// there, where x > 0 holds. The verdict is PROVED, and it is sound: it says
// that x > 0 holds whenever a run reaches the check, which is vacuous.
// Backs the example in thesis section 10.5.
fun main() {
  u32 n;
  u32 x = 4 * n;
  if (0 < x && x < 4) {
    __voblint_check(x > 0);  // PROVED
  }
}

// Ported from Example_Analysis_Result_Regression.thy
// (result_demo_sign_stmt1_reachable, result_demo_sign_stmt2_unreachable).
// x = 5 makes x < 0 infeasible: the then-branch is DEAD and the points around
// it stay live. 05-unreachable_dead_branch_literal.vimp is the Interval case.
fun main() {
  i32 x = 5;
  __voblint_check(0 < x); // PROVED
  i32 y;
  if (x < 0) {
    y = 1;
    __voblint_check(false); // NOWARN
  } else {
    y = 2;
  }
  __voblint_check(0 < x); // PROVED
}

// Ported from Example_Analysis_Result_Regression.thy
// (result_demo_int_stmt1_reachable, result_demo_int_stmt2_unreachable).
// x = 5 makes x < 0 infeasible: the then-branch is DEAD and the points around
// it stay live. 05-unreachable_dead_branch_literal.vimp is the Interval case,
// 19-dead_branch_sign.vimp the Sign one.
fun main() {
  i32 x = 5;
  __voblint_check(0 < x); // PROVED
  i32 y;
  if (x < 0) {
    y = 1;
    __voblint_check(false); // NOWARN
  } else {
    y = 2;
  }
  __voblint_check(0 < x); // PROVED
}

// The concrete value of total is fixed at 7, so total < 100 genuinely holds.
// Sign cannot establish it, and unlike the Interval sibling
// (04-globals/known-imprecision/01-repeated_call_site_widening.vimp) the
// reason is not widening: the sign lattice has no magnitude. total + n may
// overflow i32 as far as two nonnegative signs tell, so total is Top at the
// check; and sign_lt has no case comparing even a Positive against a
// nonzero constant. Adding contexts, a finer solver, or no widening at all
// would not change this answer.
//
// Kept next to the PROVED cases so they are not mistaken for general-purpose
// numeric precision.

global i32 total;
fun inc(i32 n) {
  total = total + n;
}
fun main() {
  total = 0;
  inc(3);
  inc(4);
  __voblint_check(total < 100); // UNKNOWN
}

// Source: Example_Sign_Domain_Ops (sign_arithmetic_regression: SNeg + SPos
// and SPos - SPos are STop; join_sign_regression: SNeg join SPos is STop).
//
// Every value here is fixed: s = -2, t = 2, a is -1 or 1. Sign loses all
// three because the seven-element lattice has no magnitude and no
// "nonzero" element. sign_plus of Negative and Positive and sign_minus of
// two Positives can land on either side of zero, so both give Top, and the
// join of Negative and Positive is Top as well, which cannot exclude 0.
fun main() {
  i32 s = -5 + 3;
  __voblint_check(s < 0); // UNKNOWN
  i32 t = 5 - 3;
  __voblint_check(0 < t); // UNKNOWN
  i32 c = __voblint_nondet_int();
  i32 a;
  if (c) { a = -1; } else { a = 1; }
  __voblint_check(a != 0); // UNKNOWN
}

// Ported from Example_Interval_Checks_Store_Only.thy
// (checks_ivl_ex_precision_over_sign). x is in [1,9] on the then-branch, so
// x < 11 always holds. Sign keeps x Positive after 0 < x, and x < 10 cannot
// narrow it further: the lattice has no magnitude. sign_lt has no case
// comparing Positive against a nonzero constant, so the check stays UNKNOWN.
// --analysis interval proves it (05-checks/precision/04-guarded_interval_trio.vimp).
fun main() {
  i32 x = __voblint_nondet_int();
  if (0 < x && x < 10) {
    __voblint_check(x < 11); // UNKNOWN
  }
}

// Procedure compute branches on a global input and is called twice from
// main with opposite-sign inputs, followed by an arithmetic use of the
// result.
//
// Concretely input = -3, result = 3, out = 300 and r = 2 at the checks.
//
// input: compute has no formals, so one activation serves both calls. Its
// entry joins input = SPos with SNeg to STop, and combine reads that STop
// back into main (also under --context entry-state, which keys on formals).
// --context call-string --context-depth 1 keeps the two call sites apart.
//
// result, out, r: each comes from SPos + SPos or SPos * SPos. Typed Sign has
// no magnitude, so it cannot exclude i32 wraparound of a sum or product of
// two positives (local + 1 at local = INT_MAX, 100 * result above
// INT_MAX / 100), and the transfer returns Top.
global i32 input, result, out;
fun compute() {
  i32 local = 1;
  if (0 < input) {
    local = local + 1;
  } else {
    local = local + 2;
  }
  result = local;
}
fun main() {
  i32 r = 0;
  input = 5;
  compute();
  r = r + 1;
  input = 0 - 3;
  compute();
  r = r + 1;
  out = 100 * result;
  __voblint_check(0 < input); // UNKNOWN
  __voblint_check(0 < result); // UNKNOWN
  __voblint_check(0 < out); // UNKNOWN
  __voblint_check(0 < r); // UNKNOWN
}

// Source: Example_Sign_Report_Regression (sign_factorial_result).
//
// n is 1 or more at every entry of factorial, so 0 < n holds concretely,
// but Sign answers UNKNOWN: the recursive argument n - 1 is Positive minus
// Positive, which sign_minus sends to Top, and factorial has one context,
// so that Top joins into the entry state (measured: n = Top at the check).
// The theory's prose blames the join of the two call sites' 3 and 4; both
// are Positive, so the recursive subtraction is the actual cause.
// Every return value is positive concretely (at most 4! = 24), but n * r
// is Top: typed Sign has no magnitude, so it cannot exclude i32 wraparound
// of a product of two positives. That Top flows into r, a and b.
// Interval sibling with entry-state contexts:
// 03-procedures/precision/06-recursive_factorial_dead_branch_no_bottom_leak.vimp.
fun i32 factorial(i32 n) {
  __voblint_check(0 < n); // UNKNOWN
  if (n < 2) {
    return 1;
  } else {
    i32 r = factorial(n - 1);
    __voblint_check(0 < r); // UNKNOWN
    return n * r;
  }
}
fun main() {
  i32 a = factorial(3);
  i32 b = factorial(4);
  __voblint_check(0 < a); // UNKNOWN
  __voblint_check(0 < b); // UNKNOWN
}

// Source: Example_Sign_Report_Regression (sign_two_call_sites_result).
//
// One callee, two call sites, no context. Both arguments are Positive, so
// the shared entry state is Positive, and concretely a = 9 and b = 16. n * n
// is Top all the same: typed Sign has no magnitude, so it cannot exclude
// i32 wraparound (n * n is negative for n = 46341). The Interval analogue
// (03-procedures/known-imprecision/01-two_call_sites_same_procedure.vimp)
// loses at the join instead; 11-graph-snapshot/10-entry_state_sign_own_domain.vimp
// is the same program under --context entry-state.
fun i32 square(i32 n) {
  return n * n;
}
fun main() {
  i32 a = square(3);
  i32 b = square(4);
  __voblint_check(0 < a); // UNKNOWN
  __voblint_check(0 < b); // UNKNOWN
}

// Every value is fixed at i32: a = -6, b = 6, y = 2, and no operation
// overflows. Sign loses all three. A product of two nonzero signs or a sum of
// two positives can leave i32 for large enough magnitudes, and a sign carries
// no magnitude, so the transfer cannot rule out the overflow and normalizes
// the result to the kind's top (sign_safe fails in arith_ik_sign). The
// assume_wraparound policy does not help: a wrapped product or sum can land on
// either side of zero.
// Split from ../precision/18-sign_operations.vimp, whose products with zero and
// whose quotients and remainders cannot overflow and keep their sign.
fun main() {
  i32 a = -2 * 3;
  __voblint_check(a < 0); // UNKNOWN
  i32 b = -2 * -3;
  __voblint_check(0 < b); // UNKNOWN
  i32 x = 1;
  i32 y = x + x;
  __voblint_check(0 < y); // UNKNOWN
}

// Same program as 00-sanity/precision/01-straight_line_proved.vimp, under Sign
// instead of Interval. Locks in the fix for #99: a purely local write no
// longer loses precision through the global slot.
fun main() {
  i32 x = 5;
  __voblint_check(0 < x); // PROVED
}

// REFUTED counterpart of 01-straight_line_sign.vimp: an exact negative write
// settles the same condition the other way. Sign carries no magnitude, but
// the sign alone decides 0 < x in both directions, so the pair pins that
// sign_lt refutes as precisely as it proves -- a one-sided fixture would let
// a regression that collapses every comparison to PROVED go unnoticed.

fun main() {
  i32 x = 0 - 5;
  __voblint_check(0 < x); // REFUTED
}

// Sign precision across a call boundary, on all three kinds of name at once:
// a caller local foo never touches (x), a declared global the callee writes
// (g), and the callee's return value (y). All three must come back Positive.
//
// g is the one that used to fail. cinit_sign_st seeds every declared global
// at SZero, and the old flow-INsensitive global summary folded that seed in
// as a real contribution alongside every write, unable to tell "before this
// write" from "after": join_sign SZero SPos = SNonNeg, and 0 < g was
// genuinely undecided. With the whole abstract state carried in the
// reachability-lifted local unknown there is no separate global summary to
// join against, so g is exactly SPos after g := 5 -- the entry seed
// contributes only at the CFG entry.
//
// See 04-intervening_write_preserves_local.vimp for the same routing
// property isolated without any call machinery at all.

global i32 g;
fun i32 foo() {
  g = 5;
  return 2;
}
fun main() {
  i32 x = 1;
  i32 y = foo();
  __voblint_check(0 < x); // PROVED
  __voblint_check(0 < g); // PROVED
  __voblint_check(0 < y);  // PROVED
}

// An assignment to an unrelated name must not perturb what is already known
// about another: y := 1 sits between x := 5 and the check on x, and x stays
// exactly SPos. No call, no global, no widening -- so this pins the transfer
// layer itself rather than a report readback: an assignment updates only
// the name it writes.
//
// 03-global_write_across_call.vimp is the same property with real
// interprocedural machinery in play; this is the isolated version.

fun main() {
  i32 x = 5;
  i32 y = 1;
  __voblint_check(0 < x); // PROVED
}

// The branch gate is generic in sound_refinement, so every domain that
// interprets it inherits the per-disjunct feasibility test -- including the
// `feasible` entry each interpretation has to list in its `defines` block for
// the filter to stay code-generatable. This is the Sign instance of
// 02-control-flow/precision/04-infeasible_disjunct_dropped.vimp: x is Positive,
// so "(x < 0) == 1" is false in every state, the branch is taken only when
// "0 < y" holds, and the join keeps y Positive rather than discarding it.
fun main() {
  i32 x = 5;
  i32 y = __voblint_nondet_int();
  if (0 < y || (x < 0) == 1) {
    __voblint_check(0 < y); // PROVED
  } else {
    __voblint_check(y < 1); // PROVED
  }
}

// Adapted from Goblint tests/regression/99-tutorials/01-first.c,
// 02-first-extend.c and 05-gstore-zero.c, merged: the tutorial's signs domain
// with the annotations its TODOs ask for. x is -5 or -7 by a nondet branch,
// so the join stays Negative and x < 0 is PROVED. The guard 8 < x on a
// Negative x is infeasible, so the then-arm is dead (its check is DEAD) and
// x is still Negative after the join. y is -5 or 0: Negative join Zero is
// NonPositive, enough for y < 1 but not for y < 0, which the nondet branch
// genuinely leaves open.
fun main() {
  i32 u = __voblint_nondet_int();
  i32 x;
  if (u) {
    x = -5;
  } else {
    x = -7;
  }
  __voblint_check(x < 0); // PROVED
  if (8 < x) {
    x = 10;
    __voblint_check(false); // NOWARN (unreachable)
  }
  __voblint_check(x < 0); // PROVED
  i32 y;
  if (u) {
    y = -5;
  } else {
    y = 0;
  }
  __voblint_check(y < 1); // PROVED
}

// x == 0 && x == 1 is self-contradictory (no integer is both), and so is
// y == 0 && y == 1; either disjunct's own two-step backward narrowing finds
// this and reduces its arm to Bottom. bfilter_lifted (Backward_Domain.thy)
// canonicalizes each arm to structural Bottom before joining, so the
// pointwise And/Or join no longer lets the other disjunct's untouched x (or
// y) location survive and override the narrowed-Bottom arm: the whole guard
// comes back witness-bottom, and the branch is recognized as unreachable.
fun main() {
  i32 x = __voblint_nondet_int();
  i32 y = __voblint_nondet_int();
  if ((x == 0 && x == 1) || (y == 0 && y == 1)) {
    __voblint_check(false); // NOWARN (unreachable)
  }
}

// A single procedure p increments the declared global counter, and main
// calls p once after setting an unrelated local. cinit_sign_st seeds every
// declared global at SZero, and the one call adds exactly 1, so SPos is the
// exact answer at the exit -- not merely SNonNeg, the weaker bound a
// whole-state summary that cannot separate "before the call" from "after"
// would be stuck with.
global i32 counter;
fun p() {
  counter = counter + 1;
}
fun main() {
  i32 local = 1;
  p();
  __voblint_check(0 < counter); // PROVED
}

// Sign proves weak signs after truncation without knowing either magnitude.
// A nonzero remainder then refines its weak sign to a strict sign.
fun main() {
  i32 n = __voblint_nondet_int();
  i32 d = __voblint_nondet_int();
  i32 q, r;
  if (n < 0 && d > 0) {
    q = n / d;
    r = n % d;
    __voblint_check(q <= 0); // PROVED
    __voblint_check(r <= 0); // PROVED
    __voblint_check(q > 0); // REFUTED
    if (r != 0) {
      __voblint_check(r < 0); // PROVED
    }
  } else if (n > 0 && d < 0) {
    q = n / d;
    r = n % d;
    __voblint_check(q <= 0); // PROVED
    __voblint_check(r >= 0); // PROVED
    if (r != 0) {
      __voblint_check(r > 0); // PROVED
    }
  } else if (d == 0) {
    q = n / d;
    __voblint_check(q == 0); // PROVED
  }
}

// Zero divided by any integer remains zero, including VIMP's zero case.
fun main() {
  i32 d = __voblint_nondet_int();
  i32 q = 0 / d;
  i32 r = 0 % d;
  __voblint_check(q == 0); // PROVED
  __voblint_check(r == 0); // PROVED
}

// check_query answers a compound condition from the domain's two queries.
// x <= y becomes not less(y, x) and y != 0 becomes not eq(y, 0). With x
// non-positive and y positive, Sign's less(+, <=0) and eq(+, 0) are both
// definitely false, so both conjuncts hold and the check is proved.
fun main() {
  i32 x = __voblint_nondet_int();
  i32 y = __voblint_nondet_int();
  if (x <= 0) {
    if (0 < y) {
      __voblint_check(x <= y && y != 0); // PROVED
    }
  }
}

// Source: Example_Sign_DG_Custom_Body (bf_entry_node_is_pre_body,
// bf_stock_keeps_the_formal, bf_caller_unaffected) and
// Example_Sign_DG_Custom_Combine (cj_agree_before_the_call,
// cj_stock_keeps_caller_after_the_call, cj_return_assignment_unaffected),
// the stock-specification halves of both witnesses.
//
// mark's formal p stays Positive across the procedure-entry edge and after
// mark's own first command. mark writes r, a name main also holds; the
// return combine discards the callee's locals, so main's r is still
// Positive after the call and z receives the Positive return value.
// Sign sibling of 03-procedures/precision/03-callee_local_does_not_leak.vimp.
fun i32 mark(i32 p) {
  __voblint_check(0 < p); // PROVED
  i32 r = 0 - 1;
  __voblint_check(0 < p); // PROVED
  __voblint_check(r < 0); // PROVED
  return p;
}
fun main() {
  i32 r = 1;
  __voblint_check(0 < r); // PROVED
  i32 z = mark(7);
  __voblint_check(0 < r); // PROVED
  __voblint_check(0 < z); // PROVED
}

// Source: Example_Sign_Report_Regression (sign_dead_branch_bot_result,
// sign_flow_sensitive_global_result) and Example_Sign_Unit_Assembly
// (sign_assembly_demo_report).
//
// main writes Gx = 0, then f(5) writes Gx = 1 on its live arm. Sign refutes
// n < 0 for n Positive, so the Gx = -1 arm is Bottom and never joins into
// f's exit; and the callee's write reaches main through the local unknown,
// so Gx = 0 before the call never joins with Gx = 1 after it. Either leak
// would leave Gx at Top or NonNegative and the check UNKNOWN. The
// dead-arm-free half of this program is 03-global_write_across_call.vimp.
global i32 Gx;
fun f(i32 n) {
  if (n < 0) {
    Gx = -1;
  } else {
    Gx = 1;
  }
}
fun main() {
  Gx = 0;
  f(5);
  __voblint_check(0 < Gx); // PROVED
}

// Source: Example_Sign_Domain_Ops (sign_of_int_regression,
// sign_arithmetic_regression, join_sign_regression, aval_sign_regression,
// assign_sign_regression, sign_direct_comparisons,
// sign_direct_guard_refinement, sign_interface_regression,
// sign_division_remainder_regression).
//
// Each block exercises one sign operation through a check. The UNKNOWN rows
// b < 0, d > 0 and q > 0 are soundness rows: b is -1 or 0, d is 1 or 0, and
// q is n / c with both positive, so each condition holds in one execution
// and fails in another. The products with zero, quotients and remainders
// here cannot leave i32, so they keep their sign. Products of nonzero signs
// and sums of positives may overflow and lose it; they are in
// ../known-imprecision/07-nonzero_operands_may_wrap.vimp, and other
// operations that lose information on fixed values in
// ../known-imprecision/02-mixed_signs_lose_sign.vimp.
fun main() {
  i32 c = __voblint_nondet_int();
  i32 n = __voblint_nondet_int();
  i32 z = 0 * n;
  __voblint_check(z == 0); // PROVED
  i32 x = 1;
  __voblint_check(0 < x); // PROVED
  i32 b;
  if (c) { b = -1; } else { b = 0; }
  __voblint_check(b <= 0); // PROVED
  __voblint_check(b < 0); // UNKNOWN
  i32 d;
  if (c) { d = 1; } else { d = 0; }
  __voblint_check(d >= 0); // PROVED
  __voblint_check(d > 0); // UNKNOWN
  i32 m = -1;
  __voblint_check(0 < (m <= 0)); // PROVED
  __voblint_check((m > 0) == 0); // PROVED
  __voblint_check((m >= 0) == 0); // PROVED
  __voblint_check(0 < (m != 0)); // PROVED
  if (n > 0) {
    __voblint_check(0 < n); // PROVED
  }
  if (n <= 0) {
    __voblint_check(n < 1); // PROVED
  }
  if (n >= 0) {
    __voblint_check(n > -1); // PROVED
  }
  if (n != 0) {
    __voblint_check(true); // PROVED
  } else {
    __voblint_check(n == 0); // PROVED
  }
  if (n >= 0) {
    if (n <= 0) {
      __voblint_check(n == 0); // PROVED
    }
  }
  if (n > 0) {
    if (n < 0) {
      __voblint_check(false); // NOWARN
    }
  }
  if (n > 0 && c > 0) {
    i32 q = n / c;
    __voblint_check(q >= 0); // PROVED
    __voblint_check(q > 0); // UNKNOWN
    q = n / 0;
    __voblint_check(q == 0); // PROVED
  }
  if (n < 0) {
    i32 r = n % 0;
    __voblint_check(r < 0); // PROVED
  }
}

// Source: Example_Sign_Mixed_Flow (mf_report, mf_checks_hold).
