// Adapted from Goblint tests/regression/31-ikind-aware-ints/16-enums-compare.c,
// the else arm of if (z == 3), expressed here as if (z != 3), with y = 3:
// every execution there has z != 3, so
// y == z is concretely false and (y != z) concretely true (Goblint: FAIL,
// bare, through the enums domain's exclusion set). The false arm of an
// equality guard removes the single point 3 from z, and an interval is convex:
// the full i32 range minus {3} is still the full i32 range. With z unchanged, the equality
// against y = [3,3] is UNKNOWN in both polarities. int agrees: none of sign,
// parity or congruence can exclude a single point either.
fun main() {
  i32 z = __voblint_nondet_int();
  i32 y = 3;
  if (z != 3) {
    __voblint_check(y == z); // UNKNOWN
    __voblint_check(y != z); // UNKNOWN
  }
}

// Adapted from Goblint tests/regression/36-apron/94-simple-apron-interval.c
// (Mine's counting loop, HOSC 2006); Goblint's interval configuration marks
// all three UNKNOWN as well. Concretely N >= 0 after the clamp, X counts from
// 0 up to N and stops exactly at X = N, so X == N and X - N == 0 hold in every
// execution; the else arm of if (X == N) is never taken and N == 8 holds too.
// The loop head joins X = [0,0] with the widened body state and keeps X and N
// as independent intervals [0,2147483647]: the fact X = N is a relation between two
// variables and no non-relational domain retains it, so the loop exit's
// (X >= N) only bounds each side. Both equality arms then look live, N becomes
// [8,42], and N == 8 is UNKNOWN for the same reason. An octagon or a
// polyhedron would recover X = N; int agrees with interval.
fun main() {
  i32 X = 0;
  i32 N = __voblint_nondet_int();
  if (N < 0) {
    N = 0;
  }
  while (X < N) {
    X = X + 1;
  }
  __voblint_check(X - N == 0); // UNKNOWN
  __voblint_check(X == N); // UNKNOWN
  if (X == N) {
    N = 8;
  } else {
    N = 42;
  }
  __voblint_check(N == 8); // UNKNOWN
}

// Normalize and clamp an unknown input before dividing it into buckets.
// Interval keeps the upper bounds of quotient and remainder through the
// call and the joins. The lower bounds are lost for two reasons.
// q >= 0 and bin >= 0 are undetermined: -n wraps to -2147483648 when
// n = -2147483648, so q and bin can be -536870912.
// r >= 0 always holds, since -2147483648 % 4 == 0. Mechanism: after the
// clamp n is -2147483648 or in [0,23], and the interval hull
// [-2147483648,23] loses that the outlier is divisible by 4, so r is
// [-3,3].
fun i32 bucket(i32 n) {
  if (n < 0) {
    n = -n;
  }
  if (n > 23) {
    n = 23;
  }
  i32 q = n / 4;
  i32 r = n % 4;
  __voblint_check(q >= 0); // UNKNOWN
  __voblint_check(q <= 5); // PROVED
  __voblint_check(r >= 0); // UNKNOWN
  __voblint_check(r < 4); // PROVED
  return q;
}

fun main() {
  i32 input = __voblint_nondet_int();
  i32 bin = bucket(input);
  __voblint_check(bin >= 0); // UNKNOWN
  __voblint_check(bin <= 5); // PROVED
  __voblint_check(bin != 6); // PROVED
  i32 label;
  if (bin == 0) {
    label = 0;
  } else if (bin <= 3) {
    label = 1;
  } else {
    label = 2;
  }
  __voblint_check(label >= 0); // PROVED
  __voblint_check(label <= 2); // PROVED
  __voblint_check(1 == 2 < 3); // PROVED
}

// manifests/vimp-grammar.yaml's exp_paren production (added during the grammar-
// unification investigation) makes arithmetic parentheses actually change
// precedence, not just parse harmlessly: (a+b)*c and a+b*c differ. Values
// are exact, so both checks are decidable under Interval.
fun main() {
  i32 a = 1;
  i32 b = 2;
  i32 c = 3;
  i32 x = (a + b) * c;
  __voblint_check(x == 9); // PROVED
  i32 y = a + b * c;
  __voblint_check(y == 7); // PROVED
}

// C-style unified expressions make a comparison an ordinary int-valued exp
// (0 or 1), so it can itself be an operand of another comparison, not only
// the top-level condition of if/assume. LT and EQEQ are both `assoc: none`
// at the same precedence (manifests/vimp-grammar.yaml), so the outer comparison needs
// explicit parens: `(x < 0) == 1`. x is a concrete negative literal, so the
// inner comparison's value is exact and the outer one is decidable too --
// this exercises aval's nested-boolean-as-value path independently of the
// top-level branch/assume gate (branch_lifted's own case split, exercised
// separately by the 06-reachability fixtures).
fun main() {
  i32 x = 0 - 1;
  __voblint_check((x < 0) == 1); // PROVED
}

// Adapted from Goblint tests/regression/31-ikind-aware-ints/16-enums-compare.c.
// x and y are each 0 or 1 by a nondet branch, so x = [0,1] exactly. All six
// comparison operators use their direct VIMP syntax. Thresholds walk
// across the interval so each operator is exercised at PROVED, UNKNOWN and
// REFUTED (Goblint: bare, UNKNOWN!, FAIL).
//
// The UNKNOWN rows are soundness cases inside a precision fixture, kept here
// so the operator walk stays in one place: x < 1, x == 1, x == y and their
// negations are each true in some execution and false in another, so UNKNOWN
// is the only sound answer. The final z == 3 arm shows equality refinement to
// [3,3]; its else arm's two checks are in
// known-imprecision/01-equality_else_arm_no_exclusion_set.vimp. int gives the
// same verdicts.
fun main() {
  i32 top = __voblint_nondet_int();
  i32 top2 = __voblint_nondet_int();
  i32 x;
  if (top) {
    x = 1;
  } else {
    x = 0;
  }
  i32 y;
  if (top2) {
    y = 1;
  } else {
    y = 0;
  }
  __voblint_check(x < 2); // PROVED
  __voblint_check(x < 1); // UNKNOWN
  __voblint_check(x < 0); // REFUTED
  __voblint_check(x <= 2); // PROVED
  __voblint_check(x <= 1); // PROVED
  __voblint_check(x <= 0); // UNKNOWN
  __voblint_check(x <= -1); // REFUTED
  __voblint_check(x > -1); // PROVED
  __voblint_check(x > 0); // UNKNOWN
  __voblint_check(x > 1); // REFUTED
  __voblint_check(x >= -1); // PROVED
  __voblint_check(x >= 0); // PROVED
  __voblint_check(x >= 1); // UNKNOWN
  __voblint_check(x >= 2); // REFUTED
  __voblint_check(x == y); // UNKNOWN
  __voblint_check(x == 1); // UNKNOWN
  __voblint_check(x == 2); // REFUTED
  __voblint_check(x != y); // UNKNOWN
  __voblint_check(x != 1); // UNKNOWN
  __voblint_check(x != 2); // PROVED
  i32 z = __voblint_nondet_int();
  y = 3;
  if (z == 3) {
    __voblint_check(y == z); // PROVED
    __voblint_check(y != z); // REFUTED
  }
}

// Adapted from Goblint tests/regression/36-apron/94-simple-apron-interval.c
// (Mine's counting loop, HOSC 2006), keeping the checks Goblint's interval
// configuration proves. N is nondet and clamped to [0,2147483647]; the loop
// head widens X to [0,2147483647] and (X >= 0), (N >= 0) hold after the loop. The
// equality branch writes 8 or 42 and the join gives N = [8,42], so the bound
// checks N >= 8 and N <= 42, written with < and !, are PROVED. The equality
// checks X == N, X - N == 0 and N == 8 are in
// known-imprecision/02-counting_loop_nonrelational_join.vimp. int agrees.
fun main() {
  i32 X = 0;
  i32 N = __voblint_nondet_int();
  if (N < 0) {
    N = 0;
  }
  while (X < N) {
    X = X + 1;
  }
  __voblint_check(X >= 0); // PROVED
  __voblint_check(N >= 0); // PROVED
  if (X == N) {
    N = 8;
  } else {
    N = 42;
  }
  __voblint_check(N >= 8); // PROVED
  __voblint_check(N <= 42); // PROVED
}

// Relational comparisons bind more tightly than equality on either side.
// The parenthesized variants distinguish the opposite grouping.
fun main() {
  __voblint_check(2 == 3 < 4); // REFUTED
  __voblint_check((2 == 3) < 4); // PROVED
  __voblint_check(2 < 3 == 1); // PROVED
  __voblint_check(2 < (3 == 1)); // REFUTED
  __voblint_check(2 >= 3 != 0); // REFUTED
  __voblint_check(2 >= (3 != 0)); // PROVED
}

// Both divisors are feasible: zero contributes quotient 0 and remainder 7;
// one contributes quotient 7 and remainder 0 under VIMP's total semantics.
fun main() {
  i32 d = __voblint_nondet_int();
  if (0 <= d && d <= 1) {
    i32 q = 7 / d;
    i32 r = 7 % d;
    __voblint_check(q >= 0); // PROVED
    __voblint_check(q <= 7); // PROVED
    __voblint_check(r >= 0); // PROVED
    __voblint_check(r <= 7); // PROVED
  }
}

// Division by a unit must preserve the finite endpoint of an unbounded range.
// In the n <= -7 arm, n / -1 wraps to -2147483648 when n = -2147483648, so
// positive >= 7 is undetermined and UNKNOWN is exact.
fun main() {
  i32 n = __voblint_nondet_int();
  i32 positive, negative;
  if (n >= 7) {
    positive = n / 1;
    negative = n / -1;
    __voblint_check(positive >= 7); // PROVED
    __voblint_check(negative <= -7); // PROVED
  } else if (n <= -7) {
    negative = n / 1;
    positive = n / -1;
    __voblint_check(negative <= -7); // PROVED
    __voblint_check(positive >= 7); // UNKNOWN
  }
}

// A literal is one exact value of its kind, however narrow the host's native
// int: the lexer reads digits into an arbitrary-precision integer, so the
// browser build's 31-bit ints and the native 63-bit ints keep 2^30 and
// 2^63 - 1 exact.
fun main() {
  i32 x = 1073741824;
  __voblint_check(x == 1073741823 + 1); // PROVED
  i64 y = 9223372036854775807;
  __voblint_check(y - 9223372036854775806 == 1); // PROVED
  __voblint_check(y > 9223372036854775806); // PROVED
}

// C's remainder carries the sign of its dividend, so x % 6 is 5 where x is
// positive and -1 where x is negative. n is bounded, so x = 6n + 5 stays in
// [-595,605] without overflow and both cases happen: n = -1 gives x = -1,
// and -1 % 6 is -1, not 5.
//
// Congruence keeps the class 5 (mod 6), and the Int product bounds a to
// [-1,5], which leaves exactly -1 and 5, so a guard on the sign splits the
// two and each arm holds a singleton. Neither component decides an arm
// alone: Interval on its own stops at [-5,5] because it never learns the
// class, and Congruence alone cannot rule out overflow of 6 * n and gives a
// Top. Unbounded, 6 * n + 5 wraps to every odd i32 and the remainder to every
// odd value in [-5,5] (../soundness/02-remainder_sign_undetermined.vimp).
fun main() {
  i32 n = __voblint_nondet_int();
  if (-100 <= n && n <= 100) {
    i32 x = 6 * n + 5;
    i32 a = x % 6;
    __voblint_check(a >= -1); // PROVED
    __voblint_check(a <= 5); // PROVED
    __voblint_check(a != 0); // PROVED
    if (a < 0) {
      __voblint_check(a == -1); // PROVED
    } else {
      __voblint_check(a == 5); // PROVED
    }
  }
}

// Quotient and remainder bounds over ranges: a positive range by a positive
// divisor range, its negation, a divisor range that straddles zero, and the
// remainder of a non-negative and a negative dividend range. Division by the
// constant 0 is 0 under VIMP's total semantics for any dividend.
//
// Ported from Example_Guard_Refinement.thy:
// interval_division_remainder_regression (its bot cases are domain-internal).
fun main() {
  i32 a = __voblint_nondet_int();
  i32 b = __voblint_nondet_int();
  i32 c = __voblint_nondet_int();
  i32 d = __voblint_nondet_int();
  i32 e = __voblint_nondet_int();
  if (7 <= a && a <= 9 && 2 <= b && b <= 3 && -1 <= c && c <= 1
      && 0 <= d && d <= 20 && -20 <= e && e <= -1) {
    i32 q1 = a / b;
    __voblint_check(q1 >= 2); // PROVED
    __voblint_check(q1 <= 4); // PROVED
    i32 q2 = -a / b;
    __voblint_check(q2 >= -4); // PROVED
    __voblint_check(q2 <= -2); // PROVED
    i32 q3 = a / c;
    __voblint_check(q3 >= -9); // PROVED
    __voblint_check(q3 <= 9); // PROVED
    i32 r1 = d % 3;
    __voblint_check(r1 >= 0); // PROVED
    __voblint_check(r1 <= 2); // PROVED
    i32 r2 = e % 3;
    __voblint_check(r2 >= -2); // PROVED
    __voblint_check(r2 <= 0); // PROVED
  }
  i32 t = __voblint_nondet_int();
  __voblint_check(t / 0 == 0); // PROVED
}

// Each equality holds for one feasible divisor and fails for the other.
// Dropping the totalized zero case would incorrectly decide these checks.
fun main() {
  i32 d = __voblint_nondet_int();
  if (0 <= d && d <= 1) {
    i32 q = 7 / d;
    i32 r = 7 % d;
    __voblint_check(q == 0); // UNKNOWN
    __voblint_check(q == 7); // UNKNOWN
    __voblint_check(r == 0); // UNKNOWN
    __voblint_check(r == 7); // UNKNOWN
  }
}

// The usual reading of x % 6 is "somewhere in 0..5", and for an unconstrained
// dividend C does not promise that: with x = 6n + 5, n = 0 gives a = 5 and
// n = -1 gives a = -1. Both a satisfying and a violating execution exist for
// each check below, so UNKNOWN is the only sound answer here, not a lost
// bound. The precision case next door shows what a guard on the sign recovers.
fun main() {
  i32 n = __voblint_nondet_int();
  i32 x = 6 * n + 5;
  i32 a = x % 6;
  __voblint_check(a >= 0); // UNKNOWN
  __voblint_check(a == 5); // UNKNOWN
}

