// Canonical CFG snapshot coverage: a self-recursive procedure (factorial).
// The context-insensitive analysis keys every recursive
// activation of fact into the same context (cluster_ctx_1), giving a small,
// deterministic graph with a self-loop EnterEdge (fact_pp2_ctx1 back into
// fact_entry_fact_ctx1) not exercised by 11-graph-snapshot/02-call_return.vimp's
// plain caller/callee pair. Verdict is UNKNOWN, not PROVED, and the mechanism
// is that collapse: every recursive activation of fact shares one context key,
// so the callee-entry seed is the join over all depths, and interval widening
// at the resulting self-loop drives the accumulating product to an unbounded
// bound. It is the *context-insensitive* keying that loses this, not recursion
// as such -- 03-procedures/precision/06 proves the same recursive factorial
// exactly under --context entry-state, where each depth gets its own key.

fun i32 fact(i32 n) {
  if (n < 2) {
    return 1;
  } else {
    i32 tmp = fact(n - 1);
    return n * tmp;
  }
}
fun main() {
  i32 r = fact(3);
  __voblint_check(0 < r); // UNKNOWN
}

// Adapted from Goblint tests/regression/82-widen/02-loop_increment.c,
// whose loops exit on a != 3 / b != 4. Goblint expects both checks only
// under solvers.td3.widen_gas 5: the gas lets the head grow [0,0], [0,1],
// ..., [0,3] step by step until the interval stabilizes on its own.
//
// Voblint has no widening gas. The head widens a from [0,1] to the i32
// limit, and the loop guard (a != 3) refines nothing in intervals -- a
// disequality cannot cut a hole out of an interval -- so narrowing has no
// upper bound to recover. a + 1 may then overflow, so under the default
// assume_top a is the full i32 range [-2147483648,2147483647] at the check
// (measured). Same for b. Solver-invariant across join, per-origin, warrow,
// warrow-per-origin.
fun main() {
  i32 a = 0;
  while (a != 3) {
    __voblint_check(a < 3); // UNKNOWN
    a = a + 1;
  }
  i32 b = 0;
  while (b != 4) {
    __voblint_check(b < 4); // UNKNOWN
    b = b + 1;
  }
}

// Adapted from Goblint tests/regression/82-widen/06-post_loop1.c: b
// accumulates max(b, a) over a counted loop a < 5, so b == 4 on exit.
// Goblint expects b < 5 only under solvers.td3.widen_gas 6, which delays
// widening long enough for a to settle at [0,4] and b along with it.
//
// Voblint answers UNKNOWN. Mechanism: the head widens both variables on
// the first revisit; narrowing recovers a = [0,5] at the head because
// the guard a < 5 cuts a, but no guard mentions b, and b := max(b, a)
// reads b's own widened value back, so every re-evaluation of the body
// returns [0,2147483647] for b and the head keeps it (measured:
// b = [0,2147483647]
// at the head and the check). Narrowing descends only through a guard,
// never through an accumulator's self-dependency.
// Solver-invariant across join, per-origin, warrow, warrow-per-origin.
fun main() {
  i32 b = 0;
  i32 a = 0;
  while (a < 5) {
    b = max(b, a);
    a = a + 1;
  }
  __voblint_check(b < 5); // UNKNOWN
}

// Adapted from Goblint tests/regression/82-widen/12-mihaila-widen-slide-
// delay.c (Mihaila, "Widening as Abstract Domain" slides): y is a flag set
// to 1 once x passes 5 inside a loop stepping x by 4 up to 100. Goblint
// expects all four checks only under ana.widen.delay.local 3: on the
// head's third revisit y has already reached its final [0,1], so the
// delayed widening leaves it alone and widens x only.
//
// Voblint has no widening delay. The head's first revisit widens x to
// [0,2147483647]; the second revisit is the first time y grows ([0,0] to
// [0,1]) and it is widened at once to [0,2147483647] (measured at every
// check).
// No guard in the loop or after it mentions y, so narrowing recovers the
// bound of x but has nothing to descend y through; 0 <= y survives only
// because the lower bound never moved. Solver-invariant across join,
// per-origin, warrow, warrow-per-origin.
fun main() {
  i32 x = 0;
  i32 y = 0;
  while (x < 100) {
    __voblint_check(y >= 0); // PROVED
    __voblint_check(y <= 1); // UNKNOWN
    if (5 < x) {
      y = 1;
    }
    x = x + 4;
  }
  __voblint_check(y >= 0); // PROVED
  __voblint_check(y <= 1); // UNKNOWN
}

// Adapted from Goblint tests/regression/56-witness/26-mine-tutorial-ex4.6.c
// (Mine's tutorial, example 4.6): a counter runs from 40 down to 0 and
// exits on x != 0. Goblint proves the in-loop bounds only by unassuming
// a YAML witness (26-mine-tutorial-ex4.6.yml); the post-loop x == 0 needs
// no witness.
//
// Voblint proves x == 0 but neither in-loop bound. Mechanism: the head
// widens x from [40,40] against [39,40] and drops the lower bound to
// -2147483648. On that interval x - 1 may underflow, so the decrement
// yields the full i32 range and the head becomes top; the guard (x != 0)
// excludes only the single value 0, which is not a bound. x == 0 holds
// because the exit edge asserts equality. The same program under
// --analysis int (16-composite-domain/known-imprecision/
// 02-mine_ex46_decreasing_counter.vimp) loses the bounds the same way.
fun main() {
  i32 x = 40;
  while (x != 0) {
    __voblint_check(x <= 40); // UNKNOWN
    x = x - 1;
    __voblint_check(x >= 0); // UNKNOWN
  }
  __voblint_check(x == 0); // PROVED
}

// Adapted from Goblint tests/regression/56-witness/29-mine-tutorial-ex4.10.c
// (Mine's tutorial, example 4.10): v starts at 1 and steps by 2 while
// v <= 50 (v < 51 here), so v == 51 on exit. Goblint runs it under Apron
// polyhedra with an unassumed witness and asserts only the bounds
// 51 <= v <= 52; the v == 51 check is added here.
//
// Voblint proves every bound: the head widens v to [1,2147483647] and narrows
// it back to [1,52] against v < 51 stepping by 2. The exact exit value
// stays UNKNOWN because an interval cannot express "odd": narrowing stops
// at v = [51,52] (measured), one element too wide, and nothing in the
// program refines that further. Solver-invariant across join, per-origin,
// warrow, warrow-per-origin. Under --analysis int (16-composite-domain/
// precision/05-...congruence.vimp) oddness cuts [1,50] to [1,49] in the
// body, so the head holds [1,51] and the exit guard leaves v = 51.
fun main() {
  i32 v = 1;
  while (v < 51) {
    __voblint_check(v >= 1); // PROVED
    v = v + 2;
    __voblint_check(v <= 52); // PROVED
  }
  __voblint_check(v >= 51); // PROVED
  __voblint_check(v <= 52); // PROVED
  __voblint_check(v == 51); // UNKNOWN
}

// Adapted from Goblint tests/regression/82-widen/03-loop_conditional_side.c:
// a loop exiting on i != 10 contains a branch 11 < i that is dead in every
// concrete run and would write g := 42. Goblint expects g != 42 only
// under solvers.td3.widen_gas 11 (with exp.earlyglobs), gas enough for i
// to reach [0,10] before any widening.
//
// Same mechanism as 01-neq_exit_loop.vimp, observed through a global
// instead of the counter: the head widens i to the i32 limit and the guard
// (i != 10) refines nothing, so the concretely dead branch 11 < i is
// abstractly live, g := 42 joins into g = [0,42] and the head widens that
// to [0,2147483647] (measured after the loop). The imprecision escapes the loop
// through a variable the loop never checks. Solver-invariant across join,
// per-origin, warrow, warrow-per-origin.
global i32 g;
fun main() {
  i32 i = 0;
  g = 0;
  while (i != 10) {
    if (11 < i) {
      g = 42;
    }
    i = i + 1;
  }
  __voblint_check(g != 42); // UNKNOWN
}

// Permanent regression for the certified Interval widening backend
// (docs/... the warrowing/widening solver bridge fixed for issue #96):
// before that fix, this two-line self-referential global write could make
// the join-only Interval backend diverge, because the side-effecting
// global-summary constraint for `total` folded the write's result back into
// its own current value -- a fixpoint dependency that exists even without
// any source-level loop.
//
// Base-style migration acceptance case: `total` now lives in the same
// reachability-lifted local unknown as every local, so there is no
// separate flow-insensitive global summary for its write to fold back
// into in the first place. Termination and precision now coincide -- the
// mechanism that used to cost both is gone, not merely worked around.
global i32 total;
fun main() {
  total = 0;
  total = total + 3;
  __voblint_check(0 < total); // PROVED
}

// Call-mediated sibling of 01-global_self_feedback.vimp: the same
// self-referential global write, but routed through a procedure call's
// enter/combine handling rather than a direct assignment.
//
// Base-style migration acceptance case: with the whole abstract state
// lifted into the local unknown, `total`'s write reaches the check exactly
// through the call's own combine step, with no separate global summary to
// lose precision (or termination) in -- this additionally exercises that
// the fix holds across the interprocedural global-summary path, not only
// the intraprocedural one 01-global_self_feedback.vimp isolates.
global i32 total;
fun inc(i32 n) {
  total = total + n;
}
fun main() {
  total = 0;
  inc(3);
  __voblint_check(0 < total); // PROVED
}

// Adapted from Goblint tests/regression/82-widen/07-post_loop2.c: a is a
// nondeterministic value clamped to [-9,9], then repeatedly mapped to
// -2 * (a - 1) while -10 < a < 10, so on exit -16 <= a <= 20. Goblint
// expects both bounds only under solvers.td3.widen_gas 5 together with
// exp.no-narrow.
//
// Voblint proves both by narrowing alone: the head widens a to the full
// i32 range, narrowing brings it back to [-16,20] because the guard
// admits only [-9,9] into the body and doubling that range gives
// [-16,20] (measured at the head and at both checks). The clamp is two
// assignments because a special call cannot nest inside another call.
// Solver-invariant across join, per-origin, warrow, warrow-per-origin.
fun main() {
  i32 u = __voblint_nondet_int();
  i32 t = min(9, u);
  i32 a = max(-9, t);
  while (-10 < a && a < 10) {
    a = -2 * (a - 1);
  }
  __voblint_check(a >= -16); // PROVED
  __voblint_check(a <= 20); // PROVED
}

// Every CFG node carries its own computed abstract state here, not just
// check nodes.
// Same program as 02-control-flow/precision/02-while_loop.vimp so the loop
// head's widened/narrowed interval is visible mid-loop, not only at the
// one check near the end.

fun main() {
  i32 x = 0;
  while (x < 10) {
    x = x + 1;
  }
  __voblint_check(0 < x);
}

// Same program as 03-procedures/precision/04-two_call_sites_entry_state.vimp.
// square is entered with n=[3,3] and with n=[4,4]. The solver keeps the two
// entry-state contexts apart -- that is what lets main's checks (a==9, b==16)
// come back PROVED -- and the graph draws one cluster per context, each node
// carrying its own context's state rather than the join [3,4].

fun i32 square(i32 n) {
  return n * n;
}
fun main() {
  i32 a = square(3);
  i32 b = square(4);
  __voblint_check(a == 9); // PROVED
  __voblint_check(b == 16); // PROVED
}

// Entry-state full-state rendering of a node no execution reaches, the
// counterpart of 02-entry_state_contexts.vimp. f is called twice, so its body
// carries two entry-state contexts ([5,5] and [7,7]), and its n < 2 branch is
// infeasible under both.
//
// A node whose context is unreachable renders as "unreachable", not as an
// ordinary state whose variables happen to read bottom. The distinction is
// observable and not cosmetic: an empty interval prints as x=⊥, which is
// still an ordinary variable line in an ordinary state box, so a bottom
// reading drawn as a state paints dead code as a live node.
//
// The sibling else branch still renders once per context, with that context's
// own n, so suppressing the dead node costs nothing at the live ones.

fun i32 f(i32 n) {
  if (n < 2) {
    __voblint_check(n == 99); // NOWARN (unreachable)
    return 0;
  } else {
    __voblint_check(2 < n); // PROVED
    return n;
  }
}

fun main() {
  i32 a = f(5);
  i32 b = f(7);
  __voblint_check(a == 5); // PROVED
  __voblint_check(b == 7);  // PROVED
}

// The only non-Interval case in this group: full-state rendering has to read
// the solved table through whichever domain's own value constructor is in
// play, so this pins that the Sign adapter reaches the same per-node
// rendering path the Interval cases exercise -- node labels carry
// Positive/Top, not intervals.
//
// The program is 07-sign-precision/precision/04-intervening_write_preserves
// _local.vimp's; that fixture pins the check's verdict, this one pins the
// abstract state each node actually carries, including the entry nodes where
// x is still Top and the post-assignment nodes where it is Positive. A
// rendered state and a verdict are separate surfaces over the same solution,
// and only the latter is checked by a verdict fixture.

fun main() {
  i32 x = 5;
  i32 y = 1;
  __voblint_check(0 < x);
}

// min(3, 7) is 3 and max(3, 7) is 7, both fixed by the source.
//
// The concrete mechanism is congruence_min and congruence_max
// (Congruence_Special.thy), which are both the join. A residue class
// carries no order information -- congruence_lt is the constant None -- so
// the domain cannot tell which operand is smaller, and the only sound
// answer that is always available is a class containing both. Here that is
// 3 (mod 4) for each, which congruence_eqb declines on because it is not a
// singleton. Returning the join is not a shortcut: it is forced whenever
// the operands are distinct classes.
//
// The two operands agreeing is the one case that stays exact, since the
// join of a class with itself is that class. --analysis interval and
// --analysis sign both decide this program (../precision/01, ../precision/
// 02) from order information Congruence does not have.
fun main() {
  i32 x = 3;
  i32 y = 7;
  i32 z = min(x, y);
  i32 w = max(x, y);
  __voblint_check(z == 3); // UNKNOWN
  __voblint_check(w == 7); // UNKNOWN
  i32 v = min(x, x);
  __voblint_check(v == 3); // PROVED
}

// min/max special calls on concrete constants: min(3, -5) is negative,
// max(3, -5) is positive -- exact for concrete constant intervals.
fun main() {
  i32 x = 3;
  i32 y = 0 - 5;
  i32 z = min(x, y);
  i32 w = max(x, y);
  __voblint_check(z < 0); // PROVED
  __voblint_check(0 < w); // PROVED
}

// A negative argument on either side pins sign_min negative regardless of
// the other side, and symmetrically for sign_max positive -- exact here
// even at Sign's coarser granularity.
fun main() {
  i32 x = 3;
  i32 y = 0 - 5;
  i32 z = min(x, y);
  i32 w = max(x, y);
  __voblint_check(z < 0); // PROVED
  __voblint_check(0 < w); // PROVED
}

// Ported from Example_Min_Max_Regression.thy (min_max_demo_parity_z_odd,
// min_max_demo_parity_w_odd). parity_min and parity_max return one of their
// arguments, so min/max of two Odd values stays Odd rather than Top. Odd vs
// Even proves z != 0 and refutes z == 2 * x; Top would leave both UNKNOWN.
// Interval and Sign verdicts on the same program are 01 and 02.
fun main() {
  i32 x = 3;
  i32 y = 0 - 5;
  i32 z = min(x, y);
  i32 w = max(x, y);
  __voblint_check(z != 0); // PROVED
  __voblint_check(w != 0); // PROVED
  __voblint_check(z == 2 * x); // REFUTED
  __voblint_check(w == 2 * y); // REFUTED
}

