// A recursive call is one origin whose contribution to up's FunctionEntry
// seed grows with every activation, so bounded-narrowing widens it to
// [1,2147483647]. Once the guard n < 5 caps the recursive argument, the
// contribution shrinks and the rule narrows the origin back to [1,5]; with
// main's [0,0] the seed reads [0,5].
fun i32 up(i32 n) {
  __voblint_check(n <= 5); // PROVED
  if (n < 5) {
    i32 r = up(n + 1);
  }
  return 0;
}
fun main() {
  i32 z = up(0);
}

// The call p(k, k2) is one origin of p's FunctionEntry seed. The loop head
// widens both arguments to [0,2147483647], then narrows k2 one round before k,
// because k copies k2's value from the previous iteration. So the origin's
// contribution shrinks in two steps: [0,2147483647] x [0,2], then [0,2] x [0,2].
// Both steps fall in the origin's first switch from widening to narrowing,
// and at the default bound 5 the rule takes both.
// known-imprecision/05-bounded_narrowing_bound_one.vimp is the same program
// at --narrow-bound 1, which stops after the first step.
fun p(i32 a, i32 b) {
  __voblint_check(a <= 2); // PROVED
  __voblint_check(b <= 2); // PROVED
}
fun main() {
  i32 i = 0;
  i32 k = 0;
  i32 k2 = 0;
  while (i < 3) {
    p(k, k2);
    k = k2;
    k2 = i;
    i = i + 1;
  }
}

// up is entered with 0 from main and with n + 1 from its own body while
// n < 5, so its FunctionEntry seed receives [0,0] .. [5,5]. The join rule
// never widens a seed, so the entry reads exactly their join [0,5], and
// every activation returns 0, so z is exact.
//
// Ported from Example_Interval_DG_Seed_Join_Recursion.thy:
// sj_seed_is_the_join, sj_entry_is_its_seed, sj_result_keeps_the_join,
// sj_caller_result_exact. 14-recursion_seed_warrow.vimp is the warrow run;
// 11-bounded_narrowing_recursion.vimp the bounded-narrowing one.
fun i32 up(i32 n) {
  __voblint_check(n >= 0); // PROVED
  __voblint_check(n <= 5); // PROVED
  if (n < 5) {
    i32 r = up(n + 1);
    return 0;
  } else {
    return 0;
  }
}
fun main() {
  i32 z = up(0);
  __voblint_check(z == 0); // PROVED
}

// Same program as 13-recursion_seed_join.vimp under the warrow rule, which
