// Adapted from Goblint tests/regression/20-slr_term/03-3ctxs.c (a NOCHECK
// termination test; the post-loop check i == 10 is added). The same
// program under --context entry-state (16-composite-domain/precision/
// 03-3ctxs_parity_bounds_entry_state.vimp) proves it, and inlining f
// proves it in the context-insensitive analysis too, so the composite
// itself has the precision.
//
// Mechanism: f has one context-insensitive FunctionEntry unknown, fed by
// side effect from the call site inside the loop. The head's widening
// makes the call site deliver a growing i, and the entry unknown widens
// against it to the i32 limit. j + 1 may then overflow, so under the
// default assume_top f returns the full i32 range, and 1 + t may overflow
// as well. Side-effected unknowns only ever grow, so the caller's narrowing
// never reaches f's entry (measured with --graph-snapshot: entry_f j and
// the call site's t are the full i32 range, the loop body's i is
// [-2147483648,9]). After the loop the exit guard leaves i =
// [10,2147483647] with congruence top: nothing singles out 10. Distinct
// from 03-procedures/known-imprecision/01-two_call_sites_same_procedure.vimp,
// which merges two call sites; here a single call site loses to widening on the entry
// unknown that the caller's own narrowing never reaches.
fun i32 f(i32 j) {
  return j + 1;
}
fun main() {
  i32 i = 0;
  while (i < 10) {
    i32 t = f(i);
    i = 1 + t;
  }
  __voblint_check(i == 10); // UNKNOWN
}

// Adapted from Goblint tests/regression/56-witness/26-mine-tutorial-ex4.6.c
// (Mine's tutorial, example 4.6): a counter runs from 40 down to 0 and
// exits on x != 0. Goblint proves the in-loop bounds only by unassuming a
// YAML witness. The same program under --analysis interval is
// 12-widening/known-imprecision/04-mine_ex46_decreasing_counter.vimp.
//
// The composite proves only x == 0. Mechanism: Int is the product of
// Interval and Congruence (Int_Tuple_Kind.thy), and neither component
// keeps x > 0 at the head, so the interval widens x to [-2147483648,40]. x - 1 may underflow on that interval and
// yields the full i32 range, so the head becomes top and both in-loop
// bounds are UNKNOWN. x == 0 holds because the exit edge asserts equality.
fun main() {
  i32 x = 40;
  while (x != 0) {
    __voblint_check(x <= 40); // UNKNOWN
    x = x - 1;
    __voblint_check(x >= 0); // UNKNOWN
  }
  __voblint_check(x == 0); // PROVED
}

// The program of precision/01-refinement_beats_components.vimp, run with
// Interval and Congruence as two analyses in one solve. x == 3 holds: m lies
// in [0, 100], so x = 3 * m is a multiple of three in [1, 5]. Interval keeps
// x in [1, 5]. Congruence keeps nothing: it has no interval of its own to
// establish that 3 * m cannot overflow, so under the default assume_top the
// product is top (and under assume_wraparound 3 * m of a top m wraps to every
// value anyway). Only the int product passes Interval's no-overflow fact to
// Congruence, so only it obtains 3Z for x and proves x == 3; side by side the
// check stays UNKNOWN.
fun main() {
  i32 m = __voblint_nondet_int();
  if (m < 0 || m > 100) {
    m = 0;
  }
  i32 x = 3 * m;
  if (x >= 1 && x <= 5) {
    __voblint_check(x == 3); // UNKNOWN
  }
}

// 02-times_produces_congruence.vimp and 16-cross_component_emptiness.vimp
// under the default assume_top. Concretely x * 2 is even and 2 * x + 1 odd
// also after i32 wraparound, since 2 divides 2^32: y = 2 on the inner arm,
// and z == 0 never holds.
//
// x is unbounded, so the interval cannot show that the products fit, no_ov
// fails, and the congruence answers top. The interval alone keeps y in
// [1,2] and z in [0,0], so y == 2 is UNKNOWN and the dead branch is entered
// and its check REFUTED. assume_wraparound keeps both classes (the two
// precision fixtures), and so does a bound on x
// (../precision/22-assume_top_bounded_operands_keep_class.vimp).
fun main() {
  i32 x = __voblint_nondet_int();
  i32 y = x * 2;
  if (0 < y) {
    if (y < 3) {
      __voblint_check(y == 2); // UNKNOWN
    }
  }
  i32 z = 2 * x + 1;
  if (z >= 0) {
    if (z <= 0) {
      __voblint_check(false); // REFUTED
    }
  }
}

// Int answers a check component by component, as Goblint's IntDomTuple
// does, so the mode reaches a check through what the stored states know. A
// join shows the difference.
//
// n is in [-100,100], so y = 4 * n + 1 cannot overflow i32 and is 1 (mod 4).
// On the true arm the guards bound y to [-2,10], so concretely y is 1, 5 or
// 9; the false arm sets y = 4, and y > 0 holds. Congruence knows the class,
// Interval the bounds. A refinement round moves the interval onto the class
// ([1,9]) before the join, which then keeps [1,9] and proves y > 0. Without
// refinement the join gives [-2,10] and no class (1 (mod 4) joined with 4),
// and no component decides the check.
//
// once and fixpoint agree here, and on every program we tried: each later
// operation refines again, which closes the gap one round leaves. That gap is
// visible on single values (Int_Refinement_Control.thy,
// refinement_once_not_fixpoint).
// Under never, the check is not proved. ../precision/13 and ../precision/14
// are the same program under once and fixpoint.
fun main() {
  i32 n = __voblint_nondet_int();
