// The reduced product of Interval and Congruence proves x == 3, which neither
// component proves alone. m stays in [0, 100], so x = 3 * m cannot overflow
// and lies in 3Z. The guard leaves Interval with [1, 5] and Congruence with 3Z;
// only their reduction (it_refine) narrows x to the single multiple of three in
// [1, 5]. Run as separate analyses on the same program, Interval and
// Congruence each answer UNKNOWN, and so does interval,congruence, which runs
// both in one solve without reducing them (known-imprecision/
// 03-components_side_by_side_do_not_reduce.vimp).
fun main() {
  i32 m = __voblint_nondet_int();
  if (m < 0 || m > 100) {
    m = 0;
  }
  i32 x = 3 * m;
  if (x >= 1 && x <= 5) {
    __voblint_check(x == 3); // PROVED
  }
}

// x == 0 && x == 1 is self-contradictory (no integer is both), and so is
// y == 0 && y == 1; either disjunct's own two-step backward narrowing drives
// every component of x's (or y's) sign/interval/parity/congruence tuple to
// Bottom. bfilter_lifted (Backward_Domain.thy) canonicalizes each arm to
// structural Bottom before joining, so the pointwise And/Or join no longer
// lets the other disjunct's untouched x (or y) location survive and override
// the narrowed-Bottom arm: the whole guard comes back witness-bottom, and the
// branch is recognized as unreachable.
//
// The Int product reaches this through the same generic construction as Sign
// and Interval: every refinement mode interprets sound_refinement,
// which is all the lifted filtering needs, so Refine_Fixpoint -- monotone
// nowhere but reductive everywhere -- gets the precise result too.
fun main() {
  i32 x = __voblint_nondet_int();
  i32 y = __voblint_nondet_int();
  if ((x == 0 && x == 1) || (y == 0 && y == 1)) {
    __voblint_check(x == 5); // NOWARN (unreachable)
  }
}

// y := x * 2 gives y an even/mod-2-congruent-to-0 fact from Times' own
// abstract transfer, for any x (x itself is left unconstrained). Two
// nested guards then bound y to the interval [1,2] via real control flow
// (0 < y, y < 3). Interval alone only knows y in {1,2} and cannot exclude
// 1; Congruence/Sign alone know nothing about the bound at all. The
// composite intersects [1,2] with "even" and gets the singleton {2}
// exactly -- verified that neither --analysis interval nor --analysis
// sign alone proves y == 2 on this identical source (both report
// UNKNOWN), matching 01-refinement_beats_components.vimp's contrast but
// driven by real multiplication instead of an equality guard, so the
// congruence fact comes from arithmetic (Int_Arithmetic.thy's Times case)
// rather than from a solved linear equation.
//
// Run under --signed-overflow assume_wraparound: the case tests classes that
// survive wraparound modulo 2^32 on signed i32. Under Goblint's default
// assume_top a signed operation that may overflow gives both components top
// (../known-imprecision/04-assume_top_unbounded_operands_lose_class.vimp);
// with x bounded the class survives (22-assume_top_bounded_operands_keep_class).
fun main() {
  i32 x;
  i32 y = x * 2;
  i32 z;
  if (0 < y) {
    if (y < 3) {
      __voblint_check(y == 2); // PROVED
    } else {
      z = 0;
    }
  } else {
    z = 0;
  }
}

// Adapted from Goblint tests/regression/20-slr_term/03-3ctxs.c, a
// termination test carrying no checks (NOCHECK): the loop calls f(i) = i + 1
// and steps i := 1 + f(i), so i runs 0, 2, ..., 10 and the added post-loop
// check is i == 10.
//
// The composite proves it under entry-state context sensitivity: the
// interval narrows the head to [0,11] and the exit guard leaves [10,11],
// parity keeps i Even through the stride of 2, and the reduction cuts
// [10,11] to [10,10]. --analysis interval on the same source answers
// UNKNOWN with i = [10,11]. Verified with --context call-string
// --context-depth 1 as well (PROVED). Without any context
// (16-composite-domain/known-imprecision/01-3ctxs_context_insensitive_entry.vimp)
// f's single entry state is widened and never narrowed, and the same
// check answers UNKNOWN.
fun i32 f(i32 j) {
  return j + 1;
}
fun main() {
  i32 i = 0;
  while (i < 10) {
    i32 t = f(i);
    i = 1 + t;
  }
  __voblint_check(i == 10); // PROVED
}

// Adapted from Goblint tests/regression/56-witness/29-mine-tutorial-ex4.10.c
// (Mine's tutorial, example 4.10): v starts at 1 and steps by 2 while
// v <= 50 (v < 51 here), so v == 51 on exit. Goblint runs it under Apron
// polyhedra with an unassumed witness and asserts only the bounds; the
// v == 51 check is added here.
//
// The composite proves the exact exit value. The interval alone narrows
// to v = [51,52] and answers v == 51 UNKNOWN (12-widening/
// known-imprecision/05-mine_ex410_stride2_parity.vimp). Here v := v + 2
// keeps congruence 1 (mod 2) and parity Odd through the loop, and the
// congruence-to-interval reduction rounds [51,52] down to [51,51]
// (measured at the post-loop checks). Verified that --analysis parity
// alone knows only Odd and --analysis sign only Positive, so the exact
// value comes from the reduction, not from any single component.
fun main() {
  i32 v = 1;
  while (v < 51) {
    __voblint_check(v >= 1); // PROVED
    v = v + 2;
    __voblint_check(v <= 52); // PROVED
  }
  __voblint_check(v >= 51); // PROVED
  __voblint_check(v <= 52); // PROVED
  __voblint_check(v == 51); // PROVED
}

// Adapted from Goblint tests/regression/38-int-refinements/
// 01-interval-congruence.c (ana.int.refinement fixpoint): r is 2 or 7
// depending on a nondeterministic branch, so the join knows r = 2 (mod 5)
// and r = [2,7]. The guard k >= 3 then leaves [3,7], and the congruence
// rounds the lower bound up to 7 because 3..6 are not in the class, so
// Goblint refutes k < 7 (annotated FAIL). The second half mirrors it with
// 37 or 42 under l <= 41, rounding the upper bound down to 37.
//
// Voblint refutes both. This exercises the congruence-to-interval
// reduction: the interval alone leaves k = [3,7] and l = [37,41] and
// answers UNKNOWN (verified with --analysis interval on this source),
// while the composite reports k = [7,7] and l = [37,37]. The nondet
// branch is on a fresh variable so that r itself is not refined by the
// condition; only its two constant assignments reach the join.
fun main() {
  i32 c = __voblint_nondet_int();
  i32 r;
  if (c == 0) {
    r = 2;
  } else {
    r = 7;
  }
  i32 k = r;
  if (k >= 3) {
    __voblint_check(k < 7); // REFUTED
  }
  i32 m = __voblint_nondet_int();
  i32 l;
  if (m == 0) {
    l = 37;
  } else {
    l = 42;
  }
  if (l <= 41) {
    __voblint_check(37 < l); // REFUTED
  }
}

// Adapted from Goblint tests/regression/37-congruence/01-simple.c
// (Granger, "Static analysis of arithmetical congruences", 1989) with the
// post-loop division and modulo lines and their checks dropped. Goblint
// runs it with the congruence domain alone and expects d != 1, 2, 3 and
// annotates c == 4, d == 12 and e == -8 UNKNOWN, since a congruence knows
// d = 0 (mod 4) but not its value.
//
// The composite proves d == 12 as well: the interval narrows d to [9,12]
// against d < 9 stepping by 4 and the congruence-to-interval reduction
// rounds that class-aligned to [12,12] (measured; --analysis interval
// alone stays at [9,12] and answers d == 12 UNKNOWN, --analysis parity
// alone refutes only d == 1 and d == 3).
//
// c == 4 and e == -8 stay UNKNOWN by design of a non-relational domain:
// e := e - 4 * a decreases every iteration, the head widens its lower
// bound to the i32 limit, and no guard mentions e. e - 4 * a and e + d may
// then overflow, so under the default assume_top e and c are the full i32
// range with congruence top (measured). Recovering them needs the relation
// c = e + d = 4 the product does not track.
fun main() {
  i32 a = 1;
  i32 b = 2;
  i32 c = 3;
  i32 d = 4;
  i32 e = 0;
  while (d < 9) {
    b = 2 * a;
    d = d + 4;
    e = e - 4 * a;
    a = b - a;
    c = e + d;
  }
  __voblint_check(c == 4); // UNKNOWN
  __voblint_check(d != 1); // PROVED
  __voblint_check(d != 2); // PROVED
  __voblint_check(d != 3); // PROVED
  __voblint_check(d == 12); // PROVED
  __voblint_check(e == -8); // UNKNOWN
}

// Same f -> g -> h chain as 21-context-sensitivity/precision/04 (Goblint
// 80-context_gas/12 and 13), under a depth-2 call string and the composite
// Int domain. Int proves every check at this depth, including those whose
// chain exceeds it: h's collapsed contexts enter with i at intervals:
// [0,2147483646] (--graph-snapshot), the false arm of i == 0 strips the
// endpoint 0 to [1,2147483646], so the fall-through `return 13` arm is dead
// and the collapsed exit is the singleton 3. --analysis interval alone
// answers the same at this depth (measured), because Interval's own
// disequality refinement strips the endpoint; the case pins that the
// composite keeps that refinement.
fun i32 h(i32 i) {
  if (i == 0) { return 3; }
  if (0 < i) { i32 r = h(i - 1); return r; }
  return 13;
}
fun i32 g(i32 i) {
  if (i == 0) { return 2; }
  if (0 < i) { i32 r = h(i - 1); return r; }
  return 12;
}
fun i32 f(i32 i) {
  if (i == 0) { return 1; }
  if (0 < i) { i32 r = g(i - 1); return r; }
  return 11;
}
fun main() {
  i32 a = f(10); __voblint_check(a == 3);  // PROVED
  i32 b = f(8); __voblint_check(b == 3);   // PROVED
  i32 c = h(5); __voblint_check(c == 3);   // PROVED
  i32 d = f(0); __voblint_check(d == 1);   // PROVED
  i32 e = f(1); __voblint_check(e == 2);   // PROVED
  i32 x = g(0); __voblint_check(x == 2);   // PROVED
  i32 y = g(1); __voblint_check(y == 3);   // PROVED
  i32 z = f(11); __voblint_check(z == 3);  // PROVED
  i32 u = g(12); __voblint_check(u == 3);  // PROVED
  i32 v = g(20); __voblint_check(v == 3);  // PROVED
  i32 w = f(20); __voblint_check(w == 3);  // PROVED
  i32 s = h(40); __voblint_check(s == 3);  // PROVED
  i32 t = h(300); __voblint_check(t == 3); // PROVED
  i32 q = f(300); __voblint_check(q == 3);  // PROVED
}

