    __voblint_check(even == 1); // REFUTED
    __voblint_check(odd == -2); // REFUTED
    i32 r = ((12 * n + 3) / 3) % 4;
    __voblint_check(r == 1); // PROVED
    __voblint_check(r > 0); // PROVED
  }
}

// The default-policy siblings of 02-times_produces_congruence.vimp and
// 16-cross_component_emptiness.vimp, which run under assume_wraparound.
// x is bounded to [-100,100], so x * 2 and 2 * x + 1 cannot overflow i32:
// concretely y = 2 on the inner arm, and z is odd, so z == 0 never holds.
//
// Under the default assume_top, the interval shows that each product fits,
// so the congruence keeps its class (Goblint's no_ov). The composite meets
// [1,2] with 0 (mod 2) and gets y = 2, and no odd value lies in [0,0], so
// the branch is dead; the emptiness test decides that also under
// --int-refinement never (measured). Unbounded, the products may overflow,
// the congruence goes to top, and neither check is decided
// (../known-imprecision/04-assume_top_unbounded_operands_lose_class.vimp).
fun main() {
  i32 x = __voblint_nondet_int();
  if (-100 <= x && x <= 100) {
    i32 y = x * 2;
    if (0 < y) {
      if (y < 3) {
        __voblint_check(y == 2); // PROVED
      }
    }
    i32 z = 2 * x + 1;
    if (z >= 0) {
      if (z <= 0) {
        __voblint_check(false); // NOWARN
      }
    }
  }
}

// Over i32 the products wrap, so neither quotient has a fixed parity.
// 6 * n wraps to any even value, so (6 * n) / 3 can be odd (4 / 3 == 1).
// 12 * n + 3 wraps to any value that is 3 (mod 4), so its quotient by -3
// can be even, including 0 (-1 / -3 == 0). Every check is undetermined,
// so UNKNOWN is the only sound answer.
fun main() {
  i32 n = __voblint_nondet_int();
  i32 even = (6 * n) / 3;
  i32 odd = (12 * n + 3) / -3;
  __voblint_check(even % 2 == 0); // UNKNOWN
  __voblint_check(odd % 2 != 0); // UNKNOWN
  __voblint_check(even == 1); // UNKNOWN
  __voblint_check(odd == 0); // UNKNOWN
}

// Bounding witness for issue #77: a self-recursive procedure called at a
// depth (50) far exceeding the call-string bound (1). cs_route truncates
// every routed context to length <= 1 (cs_route_length,
// Call_String_Context.thy), so fact's own recursive call site produces at
// most 2 distinct call-string contexts (length 0 and length 1) no matter
// how deep the concrete recursion runs -- proved in general for any
// compiled program by compiled_call_strings_finite
// (Context_Space_Finite.thy), not just observed here. The CLI
// completes immediately rather than growing one context per recursion
// level, which is exactly the context-explosion #77 is about. The
// EXPECT-GRAPH block below now shows that directly: three clusters for a
// 50-deep recursion, the bound's own arithmetic rather than the program's
// call depth.
// The check itself stays UNKNOWN, not PROVED, and for a different reason than
// the context bound: at depth 1 the recursive call site's own context is
// truncated to a single entry, so every activation below the first shares one
// key. The callee-entry seed is again the join over those depths, and interval
// widening on the accumulating multiplication drives the result to an
// unbounded bound. Bounding context growth is what this fixture witnesses;
// recovering the value would need a key that separates depths, which is what
// --context entry-state does for the shallow case in
// 03-procedures/precision/06.

fun i32 fact(i32 n) {
  if (n < 2) {
    return 1;
  } else {
    i32 tmp = fact(n - 1);
    return n * tmp;
  }
}
fun main() {
  i32 r = fact(50);
  __voblint_check(0 < r); // UNKNOWN
}

// At call-string depth 1, g's routed context remembers only its own
// immediate call site (the call inside f's body), which is the same
// source location regardless of which f activation reaches it. The two
// activations of g -- one from f(3), one from f(10) -- therefore collapse
// onto the same routed context and widen together, so g's result, and
// everything downstream that reads it, loses precision: g's entry widens to
// p = [3,2147483647], p + p may then overflow, and under the default
// assume_top both x and y come back as the full i32 range instead of their
// exact values 6 and 20. The K1/K2
// Isabelle witnesses pin the same separation on their solved states.

fun i32 g(i32 p) { return p + p; }
fun i32 f(i32 p) { i32 t = g(p); return t; }
fun main() {
  i32 x = f(3);
  i32 y = f(10);
  __voblint_check(x == 6); // UNKNOWN
  __voblint_check(y == 20); // UNKNOWN
}

// Adapted from Goblint tests/regression/79-callstring/01-multiple_tests_h5sens_cs.c
// and 02-multiple_tests_h5ins_cs.c (ana.context.callString_length 5, i.e.
// --context call-string --context-depth 5). Every concrete result is fixed
// and no value comes near the i32 bounds: x0..x3 are 11, y0 = 5, y1 = 6,
// z0 = z1 = 2, and m is 0 after each o call. Goblint proves a(7), e(5),
// k(9) and o(5) (its widening delay tolerates about three collapsed levels)
// and reports the 02 checks UNKNOWN. Voblint proves the four a/b/c checks
// and leaves the six e, k and o checks UNKNOWN; those six are the
// imprecision this case pins. --context entry-state proves all ten.
// The call string is exact only while the deepest activation chain fits in
// K call sites. Beyond that every deeper activation carries the same
// truncated key, so one callee-entry seed is the join of their arguments.
// - a/b/c (PROVED): the joined seed contains 0 next to positive values.
//   Interval's guard refinement for i != 0 strips the endpoint 0, so the
//   seed reaching 0 < i is positive, the fall-through `return 1` stays dead,
//   and the collapsed exit is exactly 11.
// What the other families lose, measured:
// - k/h: the joined seed is i=[0,2147483646], so the collapsed context
//   admits values below 2 that the concrete run, which stops at k(2),
//   never passes; its fall-through `return 1` joins z0 and z1 to [1,2].
// - e/f: the collapsed activations return different concrete values
//   (e(1) = 3, e(3) = 4), so the shared exit grows with every round;
//   widening takes it to the i32 range, and y0, y1 read back as top.
// - o with the global m: the collapsed context is entered from three call
//   chains, warrowing widens its seed to i=[0,2147483646], the body writes
//   m := i from it, and m reads back as [0,2147483646] after each call.
global i32 m;
fun i32 a(i32 i) {
  if (i == 0) { return 11; }
  if (0 < i) { i32 r = a(i - 1); return r; }
  return 1;
}
fun i32 b(i32 i) {
  if (i == 0) { return 12; }
  if (0 < i) { i32 r = a(i - 1); return r; }
  return 2;
}
fun i32 c(i32 i) {
  if (i == 0) { return 13; }
  if (0 < i) { i32 r = b(i - 1); return r; }
  return 3;
}
fun i32 f(i32 i) {
  if (0 < i) { i32 r = e(i - 1); return r; }
  return 2;
}
fun i32 e(i32 i) {
  i32 r = f(i - 1);
  return r + 1;
}
fun i32 h(i32 i) {
  if (i == 0) { return 1; }
  if (0 < i) { i32 r = h(i - 1); return r; }
  return 0;
}
fun i32 k(i32 i) {
  i32 r;
  if (i == 2) { r = h(i - 1); return r + 1; }
  if (0 < i) { r = k(i - 1); return r; }
  return 1;
}
fun i32 o(i32 i) {
  if (0 < i) { i = i - 1; m = i; o(i); }
  return 0;
}
fun main() {
  i32 x0 = a(7); __voblint_check(x0 == 11);  // PROVED
  i32 x1 = a(8); __voblint_check(x1 == 11);  // PROVED
  i32 x2 = c(11); __voblint_check(x2 == 11); // PROVED
  i32 x3 = b(21); __voblint_check(x3 == 11); // PROVED
  i32 y0 = e(5); __voblint_check(y0 == 5);   // UNKNOWN
  i32 y1 = e(7); __voblint_check(y1 == 6);   // UNKNOWN
  i32 z0 = k(9); __voblint_check(z0 == 2);   // UNKNOWN
  i32 z1 = k(10); __voblint_check(z1 == 2);  // UNKNOWN
  m = 20; o(5); __voblint_check(m == 0); // UNKNOWN
  m = 20; o(6); __voblint_check(m == 0);  // UNKNOWN
}

// Same program as precision/12-depth5_nondet_branch_in_recursion.vimp
// (Goblint 80-context_gas/23-per-fun.c) at depth 2. The concrete result
// f(3, 3) == 0 is fixed. main -> f(3,3) -> f(2,2) keep distinct keys, but
// f(1,1), f(0,0) and every deeper level share the truncated key [f, f],
// so that one context re-enters itself with (x - 1, y - 1). Warrowing
// extrapolates its callee-entry seed down to the i32 limit, x - 1 and y - 1
// may then overflow, and under the default assume_top x and y are the full
// i32 range there (--graph-snapshot). The x == 0 arm refines x alone -- the
// domain is non-relational -- and returns y at the full i32 range, which
// propagates back up the chain to a. The nr check stays proved because
// nr(5, 5) and nr(6, 6) are different call sites and get different keys at
// any depth.
fun nr(i32 x, i32 y) {
  __voblint_check(x == y); // PROVED
}
fun i32 f(i32 x, i32 y) {
  if (x == 0) { return y; }
  i32 top = __voblint_nondet_int();
  if (0 < top) { nr(5, 5); } else { nr(6, 6); }
  i32 r = f(x - 1, y - 1);
  return r;
}
fun main() {
  i32 a = f(3, 3);
  __voblint_check(a == 0); // UNKNOWN
}

// The browser playground's example, at its default configuration. At depth 1,
// scale's call string remembers only its call site inside wrap, so wrap(1)
// and wrap(4) share one scale context and widen together: v enters as
// [1,2147483647] and the returned r, and so a and b, lose both bounds. a == 2 is
// concretely true but UNKNOWN, and 10 / (a - 2) -- concretely 10 / 0 -- is
// only a possible division by zero. record keeps one context per call site
// in main, so hits stays exact and hits == 8 is still proved. The widened v
// and a leave v * 2 and a - 2 possible signed overflows.
global i32 hits;

fun record(i32 amount) {
  hits = hits + amount;
}

fun i32 scale(i32 v) {
  return v * 2; // ARITH: WARN signed-overflow
}

fun i32 wrap(i32 w) {
  i32 r = scale(w);
  return r;
}

fun main() {
  i32 i = 0;
  while (i < 5) {
    i = i + 1;
  }
  __voblint_check(i == 5); // PROVED
  __voblint_check(i < 5); // REFUTED

  record(i);
  record(3);
  __voblint_check(hits == 8); // PROVED

  if (hits > 10) {
    record(100);
  }

  i32 a = wrap(1);
  i32 b = wrap(4);
  __voblint_check(a == 2); // UNKNOWN
  i32 share = 10 / (a - 2); // ARITH: WARN division-by-zero; WARN signed-overflow
}

