// Adapted from Goblint tests/regression/79-callstring/05-ackermann_cs.c
// (ana.context.callString_length 10). Termination witness, not a value
// check: ack(4, 1) is astronomically deep in the concrete, and the
// call-string bound is what keeps the context space finite
// (compiled_call_strings_finite). Measured cost by depth: K=3 about 1 s,
// K=4 about 5 s, K>=5 does not finish within a minute. The fixture pins
// K=3 with an explicit --timeout so a solver-level regression surfaces as
// a structured timeout rather than a hung suite. `reachable` only asserts
// the check after the call is reported.
fun i32 ack(i32 n, i32 m) {
  if (n == 0) { return m + 1; } else {
    i32 r;
    if (m == 0) { r = ack(n - 1, 1); return r; } else {
      i32 t = ack(n, m - 1);
      r = ack(n - 1, t);
      return r;
    }
  }
}
fun main() {
  i32 x = ack(4, 1);
  __voblint_check(true); // reachable
}

// Adapted from Goblint tests/regression/81-loopfree_callstring/10-nested_loops.c
// (loopfree_callstring, which has no voblint equivalent; a plain
// call-string of depth 5 is used instead, and Goblint's own annotation is
// UNKNOWN). The chain main -> f(4) -> f(3) -> f(2) -> f(1) -> f(0) -> g(2)
// -> h(2) is seven sites deep, but the value 3 is produced by h and only
// passed back, so all that matters is that f(0)'s key differs from the
// keys of the activations still recursing. At depth 5 it does: the
// collapsed f activations f(1)/f(0) are exactly the ones whose g call is
// live, and g/h return a constant. At depth 2 the answer is UNKNOWN
// (a=[0,3]): the collapsed f seed admits every i in [0,2], and its
// fall-through `return 0` arm is live through Interval's (i != 0) guard
// keeping the endpoint 0 (see known-imprecision/03 for that mechanism).
fun i32 h(i32 i) { return 3; }
fun i32 g(i32 i) { i32 r = h(i); return r; }
fun i32 f(i32 i) {
  i32 r;
  if (i == 0) { r = g(2); return r; }
  if (0 < i) { r = f(i - 1); return r; }
  return 0;
}
fun main() {
  i32 a = f(4); __voblint_check(a == 3); // PROVED
}

// Adapted from Goblint tests/regression/80-context_gas/23-per-fun.c
// (ana.context.gas_value 3 with gas_scope function; context gas has no
// voblint equivalent, and Goblint's own annotation for a == 0 is UNKNOWN).
// Two-formal recursion f(x, y) with a nondeterministic branch that calls a
// non-recursive nr(5, 5) or nr(6, 6) before recursing. Both nr call sites
// are distinct, so even at depth 1 each has its own key and x == y is
// proved inside nr; the branch merges the caller state afterwards without
// touching x or y. main -> f(3,3) -> ... -> f(0,0) is five sites, so at
// depth 5 every f activation keeps its own key and a == 0 is exact. At
// depth 2 the deeper activations f(1,1) and f(0,0) share a key
// (known-imprecision/04). --context none proves neither check.
fun nr(i32 x, i32 y) {
  __voblint_check(x == y); // PROVED
}
fun i32 f(i32 x, i32 y) {
  if (x == 0) { return y; }
  i32 top = __voblint_nondet_int();
  if (0 < top) { nr(5, 5); } else { nr(6, 6); }
  i32 r = f(x - 1, y - 1);
  return r;
}
fun main() {
  i32 a = f(3, 3);
  __voblint_check(a == 0); // PROVED
}

// Adapted from Goblint tests/regression/32-widen-context/01-on.c
// (ana.context.widen enabled). f(x) recurses on x + 1 whenever x is
// nonzero. Under i32 wraparound x + 1 passes 2147483647, wraps to
// -2147483648 and climbs back to 0, so f(1) returns 0 and a == 0 holds,
// as Goblint annotates it. f returns only from its x == 0 arm, so the
// analysis proves a == 0 without following the wrap. The bounded call
// string keeps the context space small; under --context entry-state the same
// program needs one context per x value and gives no answer within 5 s
// (21-context-sensitivity/01-entry_state_context_chain_timeout.vimp).
fun i32 f(i32 x) {
  if (x != 0) { i32 r = f(x + 1); return r; } else { return x; }
}
fun main() {
  i32 a = f(1);
  __voblint_check(a == 0); // PROVED
}

// Call-string GraphViz coverage at Congruence, the sibling of
// 05-callstring_graph_sign.vimp and 06-callstring_graph_int.vimp.
//
// This pins a crash, not a precision claim: an earlier Isabelle-side renderer
// omitted Congruence_Analysis from a domain case split, and --dot on this
// route died with "Pattern matching failed" while the text report answered
// normally. run.py fails the case on a non-zero exit.
//
// The program is a witness the route can actually decide, so the case
// stays meaningful once it renders: mid is entered under two distinct call
// strings, and each carries its own singleton through dbl, so combine
// reads back 12 and 18 exactly. Context-insensitively both are UNKNOWN at
// 0 (mod 3) -- the two call sites join to 3 (mod 3) at mid's entry.
fun i32 dbl(i32 p) { return p + p; }
fun i32 mid(i32 p) { i32 t = dbl(p); return t; }
fun main() {
  i32 x = mid(6);
  i32 y = mid(9);
  __voblint_check(x == 12); // PROVED
  __voblint_check(y == 18); // PROVED
}

// The browser playground's example at call-string depth 2. scale's context
// now also records which wrap call reached it, so wrap(1) and wrap(4) no
// longer share a context: a is exactly 2, a == 2 is proved, and the possible
// division by zero of the depth-1 run becomes a definite one.
global i32 hits;

fun record(i32 amount) {
  hits = hits + amount;
}

fun i32 scale(i32 v) {
  return v * 2;
}

fun i32 wrap(i32 w) {
  i32 r = scale(w);
  return r;
}

fun main() {
  i32 i = 0;
  while (i < 5) {
    i = i + 1;
  }
  __voblint_check(i == 5); // PROVED
  __voblint_check(i < 5); // REFUTED

  record(i);
  record(3);
  __voblint_check(hits == 8); // PROVED

  if (hits > 10) {
    record(100);
  }

  i32 a = wrap(1);
  i32 b = wrap(4);
  __voblint_check(a == 2); // PROVED
  i32 share = 10 / (a - 2); // ARITH: ERROR division-by-zero
}

// Same program as 02-depth2_separates_shared_callee.vimp at depth 3. The
// deepest call chain is two calls long, so a third frame separates nothing
// further: g's two activations keep the contexts pp2 pp5 and pp2 pp6, and
// both results stay exact.
//
// Ported from Example_Interval_Call_String_Generic_Parity.thy:
// cs_generic_k3_g_entry_first, cs_generic_k3_g_entry_second.
fun i32 g(i32 p) { return p + p; }
fun i32 f(i32 p) { i32 t = g(p); return t; }
fun main() {
  i32 x = f(3);
  i32 y = f(10);
  __voblint_check(x == 6); // PROVED
  __voblint_check(y == 20); // PROVED
}

// The boundary of what Parity can say, kept as an explicit witness so the
// PROVED cases next door are not mistaken for general-purpose precision.
// x is Even here and the concrete value is genuinely fixed (4), but the
// parity lattice has exactly four elements -- Bot, Even, Odd, Top -- and
// carries no magnitude information whatsoever, so "x is Even" is the most
// it can conclude and x == 4 stays UNKNOWN.
// The concrete mechanism: parity_classify_check decides an equality only
// when the two sides' parities are disjoint (Even vs Odd), which refutes;
// it can never confirm one, since equal parity is necessary but nowhere
// near sufficient for equal values. --analysis interval proves this same
// check outright.
fun main() {
  i32 x = 2 + 2;
  __voblint_check(x == 4); // UNKNOWN
}

// The acceptance case for Parity as a public analysis: a property provable
// from parity information alone. n is completely unconstrained, so no
// interval or sign reasoning bounds x or y at all -- but times_parity has
// PEven * _ = PEven, so 2*n is Even whatever n is, and 2*n+1 is then Odd.
// Even and Odd are disjoint, so x and y can never be equal; parity refutes
// the equality and therefore proves its negation.
// Multiplication by the literal 2 is what makes this non-relational: the
// domain evaluates each operand independently, so n+n would be Top+Top=Top
// (it cannot see the two operands are the same value), while 2*n is Even
// from the literal's own parity alone.
// This exercises the full public path: run_voblint answers
// --analysis parity from the routed-unit solved result -- the same generic
// pipeline the other domains use, with no Parity-specific result or report
// construction anywhere in it.
fun main() {
  i32 n = __voblint_nondet_int();
  i32 x = 2 * n;
  i32 y = 2 * n + 1;
  __voblint_check(x != y); // PROVED
}

// Parity through a procedure call and return, so the routed spine's own
// enter and combine edges carry the fact rather than just intra-procedural
// transfer. double's return is Even for any argument (PEven * _ = PEven),
// and the caller reads that back across the combine edge, so b+1 is Odd
// while a is Even and the two can never be equal -- provable at the call
// site even though the original argument is unconstrained.
// Context-insensitive (the default --context none): one shared callee
// context suffices here, since both calls agree on the
// callee's parity result.
fun i32 double(i32 p) { return 2 * p; }
fun main() {
  i32 n = __voblint_nondet_int();
  i32 a = double(n);
  i32 b = double(a);
  __voblint_check(a != b + 1); // PROVED
}

// An odd dividend modulo any even divisor stays odd, including divisor zero
// under VIMP's totalization. Neither operand needs a known magnitude.
fun i32 odd_remainder(i32 n, i32 d) {
  i32 dividend = n * 4 + 1;
  i32 divisor = d * 2;
  i32 r = dividend % divisor;
  return r;
}

fun main() {
  i32 n = __voblint_nondet_int();
  i32 d = __voblint_nondet_int();
  i32 r = odd_remainder(n, d);
  __voblint_check(r != 0); // PROVED
  __voblint_check(r != 2); // PROVED
  __voblint_check(r == 0); // REFUTED
}

// x == 0 && x == 1 is self-contradictory (no integer is both), and so is
// y == 0 && y == 1, so this branch is concretely unreachable. Parity's
// equality inverse gives both sides of a guard that held the meet of their
// parities: x == 1 makes x odd, then x == 0 meets odd with even and leaves
// Bottom. The y arm empties the same way, the lifted filter canonicalizes each
// empty arm to Bottom before the join, and the branch is proved dead.
fun main() {
  i32 x = __voblint_nondet_int();
  i32 y = __voblint_nondet_int();
  if ((x == 0 && x == 1) || (y == 0 && y == 1)) {
    __voblint_check(x == 5); // NOWARN (unreachable)
  }
}

// Ported from Example_Parity_Checks_Store_Only.thy (parity_ex_classify_3/4/6,
// parity_ex_report_eval). y = x * 2 is Even and z = y + 1 is Odd whatever x
// is, so y != z is PROVED and y == z REFUTED. w is an unconstrained
// __voblint_nondet_int(); Parity can only refute an equality across differing
// parities, never confirm one, and y == w is undetermined, so UNKNOWN.
fun main() {
  i32 x = __voblint_nondet_int();
  i32 y = x * 2;
  i32 z = y + 1;
  __voblint_check(y != z); // PROVED
  __voblint_check(y == z); // REFUTED
  i32 w = __voblint_nondet_int();
  __voblint_check(y == w); // UNKNOWN
}

// Ported from Example_Parity_Checks_Store_Only.thy (parity_direct_comparisons).
// A comparison is an int-valued expression. With x Even, x != 1 is decided
// (true, value 1, Odd), so ne != 0 is PROVED. Parity has no order, so
// x <= 1, x > 1 and x >= 1 evaluate to Top. Those three UNKNOWNs are sound
// answers, not regressions: n is unconstrained, so each comparison is true on
// some runs and false on others.
fun main() {
  i32 n = __voblint_nondet_int();
  i32 x = 2 * n;
  i32 le = x <= 1;
  i32 gt = x > 1;
  i32 ge = x >= 1;
  i32 ne = x != 1;
  __voblint_check(ne != 0); // PROVED
  __voblint_check(le != 0); // UNKNOWN
  __voblint_check(gt != 0); // UNKNOWN
  __voblint_check(ge != 0); // UNKNOWN
}

// Ported from Example_Parity_Checks_Store_Only.thy
// (parity_division_remainder_regression). Even % Even stays Even, including
// divisor zero under VIMP's totalization, so even_rem != 1 is PROVED.
// Odd % Odd and Odd / Even are Top, and both UNKNOWNs are sound: 1 % 3 = 1
// but 3 % 3 = 0, and 1 / 2 = 0 but 11 / 2 = 5. Odd % Even is
// 03-remainder_even_divisor.vimp.
fun main() {
  i32 n = __voblint_nondet_int();
  i32 d = __voblint_nondet_int();
  i32 even_rem = (2 * n) % (2 * d);
  __voblint_check(even_rem != 1); // PROVED
  i32 odd_rem = (2 * n + 1) % (2 * d + 1);
  __voblint_check(odd_rem != 0); // UNKNOWN
  i32 quot = (2 * n + 1) / (2 * d);
  __voblint_check(quot != 0); // UNKNOWN
}

// FM 2026 Example 2: the paper's Fig. 1 analyzed with intervals and
// widening, where the three contributions to the global g are accumulated
// into one value that is widened on every update.
//
//   [1,1]                       the initializer's contribution
//   [1,1]    \/  [-17,1]        joined with main's -17; the lower bound
//                               grew downwards, so widening drops it
//            ->  [-inf,1]
//   [-inf,1] \/  [-inf,42]      joined with f's 42; the upper bound grew,
//            ->  [-inf,+inf]    so widening drops that too
//
// so the paper fails to deduce g <= 42 and cannot rule out the error call.
//
// By default Voblint analyzes declared globals flow-sensitively (19-paper-
// examples/precision/01-fig1_sequential_globals.vimp answers Fig. 1 exactly).
// Flow-insensitively (precision/07-fig1_flow_insensitive_globals.vimp) g
// starts from its initial 0, not 1, and warrowing narrows it back to
// [-17,42]. The chain is therefore staged on a procedure's FunctionEntry
// seed, side-effected once per call site. Three call sites contribute the
// paper's own three values, in the paper's order, and Apinis warrowing walks
// the identical chain, with the i32 limits in place of -inf and +inf, to the
// full i32 range -- so x < 43 comes back UNKNOWN even though x is concretely
// one of 1, -17, 42.
//
// Mechanism, stated as the convention requires: the update rule widens the
// slot's already-joined value against each new contribution. No single
// origin's own contribution ever moves -- each call site passes one
// constant -- so both bounds are lost purely to joining across origins
// before widening. 03-per_origin_widening.vimp is the same program under
// the update rule that fixes exactly this.

fun f(i32 x) {
  __voblint_check(x < 43); // UNKNOWN
}
fun main() {
  f(1);
  f(-17);
  f(42);
}

// Baseline for FM 2026 Examples 7 and 8, both of which are definitions of
// a context C rather than precision claims of their own. Sect. 3's closing
// remark is the claim they serve: "distinguishing function calls by
// contexts, be it via callstrings or partial tabulation, has been shown to
// considerably increase analysis precision."
//
// This is the same source under no context at all, so there is one unknown
// per program point of f shared by both call sites. Mechanism: f's
// FunctionEntry seed receives 3 from one site and 10 from the other, and
// the single copy of f's body is analyzed under their join, widened to
// p = [3,2147483647]. p + p may then overflow, so f returns the full i32
// range to both callers and neither x == 6 nor y == 20 survives, though
// each is concretely exact.
//
// precision/05- and precision/06- are this program under the paper's two
// context choices; both recover the exact values.

fun i32 f(i32 p) { return p + p; }
fun main() {
  i32 x = f(3);
  i32 y = f(10);
  __voblint_check(x == 6);  // UNKNOWN
  __voblint_check(y == 20);  // UNKNOWN
}

// Seidl, Vojdani, Erhard, Schwarz, "Mixed Flow-Sensitive Static Analysis:
// Engineering Modularity" (FM 2026), Fig. 1 -- the running example behind
// the paper's Examples 1, 3 and 5. Transcribed as closely as VIMP allows:
// C's file-scope initializers `int g = 1; int h = 0;` become main's first
// two statements (VIMP globals have no initializer syntax and default to
// zero), and `if (g > 42) error();` becomes the equivalent check g < 43.
//
//   Example 1 asks whether a flow-INSENSITIVE summary of g suffices to
//   falsify the error condition. Its three contributions to g are 1 (the
//   initializer), -17 (main) and 42 (f).
//   Example 3 makes the same point for h: a flow-insensitive analysis
//   cannot tell whether line 4 runs once or many times, so it infers
//   h = [0,+inf].
//
// Both losses follow from a choice the paper states as one: "In principle,
// the values of g and h could be analyzed flow-sensitively. For efficiency,
// we may choose to analyze the values of one or both of them
// flow-insensitively."
//
// The CLI makes the other choice, as Goblint does on single-threaded code:
// a declared global lives in the same reachability-lifted local unknown as
// every other variable and is analyzed flow-sensitively through calls (see
// 04-globals/precision/09-global_through_two_callees.vimp). So g == 42 and
// h == 1 exactly, and the paper's imprecision has no occasion to arise.
// This program also answers identically under all four of --globals
// join|per-origin|warrow|warrow-per-origin: nothing about a `global` here
// exercises the update rule at all. The unknown that does is a procedure's
// FunctionEntry seed, written once per call site, and on it the paper's
// widening loss reproduces exactly -- this group's 02- and 03- cases.

global i32 g, h;
fun f() {
  h = h + 1;
  g = 42;
}
fun main() {
  g = 1;
  h = 0;
  g = -17;
  f();
  __voblint_check(g == 42);   // PROVED
  __voblint_check(h == 1);    // PROVED
  __voblint_check(g < 43);     // PROVED
}

// FM 2026 Sect. 5.3, "Recovering Precision at Globals: Update Rules" --
// the paper's first improvement over widening a global's accumulated
// value: keep the contributions separate by origin (the local that
// supplied them), widen per origin, and take the join of all origins as
// the global's value. The paper states this is "sufficient to recover a
// precise result in Example 1", since there each origin contributes at
// most one value and so no widening is needed.
//
// Same program as known-imprecision/02-whole_global_widening.vimp, which
// is that same slot under plain Apinis warrowing. Each of the three call
// sites is its own origin holding one constant, so nothing widens and the
// slot reads the join of the three -- the paper's [-17,42] for g.
//
// Both bounds are pinned, not just the paper's error condition: -18 < x
// fails under warrowing for the same reason x < 43 does, so proving the
// two together is what distinguishes the recovered [-17,42] from any
// interval merely narrow enough to decide the error condition.

fun f(i32 x) {
  __voblint_check(x < 43);      // PROVED
  __voblint_check(-18 < x);      // PROVED
}
fun main() {
  f(1);
  f(-17);
  f(42);
}

// FM 2026 Example 7: "For 1-callstring context-sensitivity, C is the set
// of call sites in the program plus the element _main, c0 = _main, and
// context_{u,f,args} _ _ = u." The context of an activation is simply the
// call site that produced it, ignoring the arguments and the state.
//
// Same source as known-imprecision/04-context_insensitive_calls.vimp,
// which loses both values to a single shared copy of f. Here f's two call
// sites are two distinct contexts, so each activation gets its own seed
// and its own copy of f's body, and both exact results survive.
//
// The paper's C is unbounded in general; Voblint's --context-depth K makes
// the bound explicit, and K = 1 is the instance Example 7 describes. See
// 17-call-string/ for what a depth of 1 cannot separate -- a callee one
// frame further down shares its own single call site across both
// activations, which is where depth 2 starts to matter.

fun i32 f(i32 p) { return p + p; }
fun main() {
  i32 x = f(3);
  i32 y = f(10);
  __voblint_check(x == 6);  // PROVED
  __voblint_check(y == 20);  // PROVED
}

// FM 2026 Example 8, partial tabulation of summary functions: "we use the
// abstract states at start points of functions to distinguish function
// calls and set C = D[start_f], c0 = d0, context_{u,f,args} d _ =
// enter_{f,args} d." The context is the entered state itself, so two
// activations share a copy of the callee exactly when they enter it in the
// same abstract state -- unlike Example 7, where the call site alone
// decides, whatever state it enters with.
//
// Same source as known-imprecision/04-context_insensitive_calls.vimp and
// as precision/05-example7_one_callstring.vimp. The two calls enter f with
// p = [3,3] and p = [10,10], two distinct entry states, so tabulation
// separates them here just as 1-callstring does, and both exact values
// survive. The paper draws no precision ordering between the two choices,
// and this pair does not claim one either: they agree on this program and
// are separated by which activations they merge, not by how precise they
// are.

fun i32 f(i32 p) { return p + p; }
fun main() {
  i32 x = f(3);
  i32 y = f(10);
  __voblint_check(x == 6);  // PROVED
  __voblint_check(y == 20);  // PROVED
}

// Seidl, Vojdani, Erhard, Schwarz, "Mixed Flow-Sensitive Static Analysis:
// Engineering Modularity" (FM 2026), Fig. 1 with both globals analyzed
// flow-insensitively -- the paper's Examples 1, 3 and 5 in one run. The
// program is 01-fig1_sequential_globals.vimp, which answers every check
// exactly because there g and h travel flow-sensitively.
//
//   Example 5: the constraint system has one unknown per program point plus
//   one per global, [g] and [h]. Each point reads only the globals its
//   statement mentions and side-effects only the global it assigns.
//   Example 1: [g] collects 1, -17 and 42 and joins them to [-17,42]. The
//   summary still proves g < 43, which rules out the error, but not g == 42.
//   Example 3: [h] collects 0 and h + 1. A flow-insensitive analysis cannot
//   tell how often f's first line runs, so h widens to its kind's maximum.
//   At the machine kind i32 the next h + 1 may overflow, which Goblint's
//   default assume_top reads as any i32 value: 0 <= h is lost along with
//   h == 1, and the overflow is reported at line 25. The paper's [0,+inf]
//   is the mathematical-integer reading.
//
// With --globals join or per-origin, [h] grows by one per round and the
// solve gave no answer within 10 s (measured for join); a widening rule is
// needed (cases 02 and 03).
global i32 g, h;
fun f() {
  h = h + 1;
  g = 42;
}
fun main() {
  g = 1;
  h = 0;
  g = -17;
  f();
  __voblint_check(g == 42);   // UNKNOWN
  __voblint_check(h == 1);    // UNKNOWN
  __voblint_check(g < 43);    // PROVED
  __voblint_check(0 <= h);    // UNKNOWN
}

// Adapted from Goblint tests/regression/34-localwn_restart/02-hybrid.c
// (Amato-Scozzari, SAS 2013, after Halbwachs-Henry, SAS 2012). Goblint
// proves 0 <= i <= 10 inside the inner loop only with
// solvers.td3.restart.wpoint.enabled (restart.wpoint.once disabled), or
// under the sl4 solver: the inner widening point must be restarted from
// bottom once the outer head narrows.
//
// Voblint answers both bounds UNKNOWN. Mechanism: the inner head is its
// own widening point, and i flows around the inner back-edge unrefined
// (the inner guard j < 10 says nothing about i). The outer head's first
// widening takes i to 2147483647, so i := i + 1 may overflow and delivers
// the full i32 range to the inner head. The outer head later narrows, but
// the inner head's right-hand side joins its value with its own back-edge
// value, so top is a self-fixpoint that narrowing never re-descends
// (measured: i is top at both checks).
// Solver-invariant across join, per-origin, warrow, warrow-per-origin.
fun main() {
  i32 i = 0;
  while (true) {
    i = i + 1;
    i32 j = 0;
    while (j < 10) {
      __voblint_check(i >= 0); // UNKNOWN
      __voblint_check(i <= 10); // UNKNOWN
      j = j + 1;
    }
    if (9 < i) {
      i = 0;
    }
  }
}

// Adapted from Goblint tests/regression/34-localwn_restart/01-nested.c
// (Halbwachs-Henry, SAS 2012: nested counted loops, i == 10 after the
// outer loop) with the in-loop checks of 56-witness/35-hh-ex1b.c folded
// in. Goblint runs 01-nested.c under td3 and slr3 and expects every check
// to hold; 35-hh-ex1b.c additionally feeds a YAML unassume witness.
//
// Voblint proves all four with plain widening and narrowing: the inner
// head widens j to the i32 limit and narrows it back to [0,10] against j < 10,
// so the outer body sees j == 10 exactly; the outer head does the same for
// i. Solver-invariant: join, per-origin, warrow and warrow-per-origin all
// answer PROVED x4, and the same program with bound 100 (35-hh-ex1b.c's
// literal shape) measures identically.
fun main() {
  i32 i = 0;
  while (i < 10) {
    i32 j = 0;
    while (j < 10) {
      j = j + 1;
      __voblint_check(j <= 10); // PROVED
    }
    __voblint_check(j == 10); // PROVED
    i = i + 1;
    __voblint_check(i <= 10); // PROVED
  }
  __voblint_check(i == 10); // PROVED
}

// Adapted from Goblint tests/regression/34-localwn_restart/06-td-a2i.c,
// the running example of "The Top-Down Solver -- An Exercise in A^2I",
// Section 6. Goblint runs it with solvers.td3.remove-wpoint and expects
// the first four checks; the post-loop j == 17 is annotated TODO there,
// i.e. Goblint cannot establish it either.
//
// Voblint proves the four in-loop and i == 42 checks: each head widens its
// own counter and narrows it back against its guard, and the inner exit
// leaves j = [17,17] for the checks in the outer body.
//
// The post-loop j == 17 is UNKNOWN by a non-relational join, not by
// widening: the outer head joins the entry state j = 0 with the back-edge
// state j = 17, giving j = [0,17] (measured), and the outer exit guard
// (i >= 42) refines only i. Recovering j == 17 there needs the relation
// "i > 0 implies j = 17", which no interval can carry.
// Solver-invariant across join, per-origin, warrow, warrow-per-origin.
fun main() {
  i32 i = 0;
  i32 j = 0;
  while (i < 42) {
    j = 0;
    while (j < 17) {
      i32 x = i + j;
      j = j + 1;
    }
    __voblint_check(j == 17); // PROVED
    __voblint_check(i >= 0); // PROVED
    __voblint_check(i <= 41); // PROVED
    i = i + 1;
  }
  __voblint_check(i == 42); // PROVED
  __voblint_check(j == 17); // UNKNOWN
}

// Adapted from Goblint tests/regression/34-localwn_restart/03-nested2.c
// (Amato-Scozzari, SAS 2013): an endless outer loop whose body runs a
// counted inner loop and then steps i := i + 11 - j. Goblint expects
// i >= 0 under td3 and slr3 with sem.int.signed_overflow assume_none.
//
// Under i32 wraparound the check is undetermined: the inner loop always
// leaves j = 10, so i grows by one per outer iteration, passes 2147483647
// and wraps to -2147483648. The run reaches the check in stores with
// i >= 0 and, after 2^31 iterations, in stores with i < 0, so UNKNOWN is
// the only sound answer.
fun main() {
  i32 i = 0;
  while (true) {
    i32 j = 0;
    while (j < 10) {
      j = j + 1;
    }
    i = i + 11 - j;
    __voblint_check(i >= 0); // UNKNOWN
  }
}

// Adapted from Goblint tests/regression/32-widen-context/01-on.c
// (ana.context.widen enabled; Goblint's default full context maps to
// --context entry-state). f(x) recurses on x + 1 whenever x is nonzero.
// Under i32 x climbs to 2147483647, wraps to -2147483648 and climbs back to
// 0, so f(1) returns 0 after about 2^32 nested calls. Every activation
// enters with a new singleton x, and entry-state keying creates one context
// per value: about 2^32 contexts. Goblint finishes here because
// ana.context.widen widens the context itself across levels; voblint has no
// context widening, and the solve gives no answer within 5 s. --timeout turns
// that into a structured "did not finish within" rejection, which is what
// this fixture pins (no verdict annotations: the runner expects the
// rejection, not a report). It shows only that no answer came within the
// bound, not that the solve diverges. A bounded call string answers the same
// program; see 17-call-string/precision/13-depth2_context_chain_wraps_to_zero.vimp.
fun i32 f(i32 x) {
  if (x != 0) { i32 r = f(x + 1); return r; } else { return x; }
}
fun main() {
  i32 a = f(1);
  __voblint_check(a == 0);
}

// Same program as precision/03-global_written_per_recursion_level.vimp
// (Goblint 79-callstring/10-inf_callstack_cs.c) under a bounded call
// string. The concrete m after each call is 0. Levels deeper than the
// bound share one truncated key, so their callee-entry seed is the join
// of every argument that reaches it from the three call chains;
// --graph-snapshot shows that collapsed context entered with
// i=[0,2147483646] (warrowing widens the accumulating seed). Its body writes m := i - 1
// from that range, so the m the caller reads back after the call is
// [0,2147483646] and never the singleton 0. Depth 10 fits the o(5) and o(8)
// chains (6 and 9 sites) and proves those two; o(25) stays UNKNOWN at any
// depth below 26.
global i32 m;
fun i32 o(i32 i) {
  if (0 < i) { i = i - 1; m = i; o(i); }
  return 0;
}
fun main() {
  m = 20;
  o(5);
  __voblint_check(m == 0); // UNKNOWN
  m = 20;
  o(8);
  __voblint_check(m == 0); // UNKNOWN
  m = 20;
  o(25);
  __voblint_check(m == 0);  // UNKNOWN
}

// Adapted from Goblint tests/regression/79-callstring/04-endless_loop_cs.c
// (ana.context.callString_length 10; Goblint annotates the inner check
// UNKNOWN). main cannot call itself in VIMP, so the recursion lives in a
// helper. rec increments the global num_iterat and recurses while it is
// positive. From num_iterat = 2 the counter wraps from 2147483647 to
// -2147483648, the innermost activation returns 2, and every res and r is
// 2: both checks are reached and fail in every store.
// Mechanism: widening takes num_iterat to the upper i32 bound, so
// num_iterat + 1 may overflow and rec is entered with the full i32 range
// (measured). The else arm then admits num_iterat == 0 and its return 5,
// so res and r are [2,5] and both checks are UNKNOWN.
global i32 num_iterat;
fun i32 rec() {
  if (0 < num_iterat) {
    num_iterat = num_iterat + 1;
    i32 res = rec();
    __voblint_check(res == 5); // UNKNOWN
    return res;
  } else {
    if (num_iterat == 0) { return 5; } else { return 2; }
  }
}
fun main() {
  num_iterat = 2;
  i32 r = rec();
  __voblint_check(r == 5); // UNKNOWN
}

// f is called twice from main with a positive and a negative literal
// argument. Sign's own entry-state routing keys the two activations of f
// by their entered p, so they stay two distinct contexts ([SPos] and
// [SNeg]) at f's single FunctionEntry node rather than joining into one
// shared summary. Concretely x = 6 and y = -20, yet both checks are
// UNKNOWN: typed Sign has no magnitude, so it cannot exclude i32
// wraparound of p + p for same-sign p, and each context returns Top.
fun i32 f(i32 p) {
  i32 t = p + p;
  return t;
}
fun main() {
  i32 x = f(3);
  i32 y = f(-10);
  __voblint_check(0 < x); // UNKNOWN
  __voblint_check(y < 0); // UNKNOWN
}

// The program of precision/12-call_string_depth_two_separates_nested_calls.vimp
// at depth 1: both activations of g share the context of f's one call site,
// so g returns the join of 3 and -10 and neither check is decided.
fun i32 g(i32 p) {
  return p;
}
fun i32 f(i32 p) {
  i32 t = g(p);
  return t;
}
fun main() {
  i32 x = f(3);
  i32 y = f(-10);
  __voblint_check(x > 0); // UNKNOWN
  __voblint_check(y < 0); // UNKNOWN
}

// Adapted from Goblint tests/regression/80-context_gas/05-circle_call_sens.c
// and 06-circle_call_ins.c (ana.context.gas_value 15; Goblint's full
// context, which gas 15 preserves for these depths, maps to --context
// entry-state). Mutual recursion f -> g -> f with non-linear results: f(i)
// = g(i-2) + g(i-3) and g(i) = f(i+1). Entry-state keys each activation by
// its entered i, so every intermediate value is a singleton and all sums
// are exact. Goblint's annotations for its 06 file are arithmetically
// wrong: the concrete values are f(13) = 1817 (annotated 233), f(20) =
// 52756 (6765), g(13) = 2940 (377), g(20) = 10946 -> 85361; Goblint never
// notices since it marks those checks UNKNOWN. voblint REFUTES the wrong
// value and PROVES the right ones (computed by direct evaluation).
// --context call-string --context-depth 5 proves only f(0) and g(0);
// --context none proves nothing.
fun i32 g(i32 i) {
  if (i == 0) { return 1; }
  if (0 < i) { i32 r = f(i + 1); return r; }
  return 11;
}
fun i32 f(i32 i) {
  if (i == 0) { return 2; }
  if (0 < i) { i32 r1 = g(i - 2); i32 r2 = g(i - 3); return r1 + r2; }
  return 12;
}
fun main() {
  i32 a = f(0); __voblint_check(a == 2);      // PROVED
  i32 b = f(7); __voblint_check(b == 101);    // PROVED
  i32 c = f(9); __voblint_check(c == 265);    // PROVED
  i32 d = f(10); __voblint_check(d == 429);   // PROVED
  i32 e = g(0); __voblint_check(e == 1);      // PROVED
  i32 h = g(3); __voblint_check(h == 25);     // PROVED
  i32 k = g(6); __voblint_check(k == 101);    // PROVED
  i32 l = g(8); __voblint_check(l == 265);    // PROVED
  i32 m = f(13); __voblint_check(m == 233);   // REFUTED
  __voblint_check(m == 1817);              // PROVED
  i32 n = f(20); __voblint_check(n == 52756); // PROVED
  i32 o = g(13); __voblint_check(o == 2940);  // PROVED
  i32 p = g(20); __voblint_check(p == 85361);  // PROVED
}

// Adapted from Goblint tests/regression/80-context_gas/01-basic_tests_bound_sens.c
// (gas 10) and 04-contextGasNeg.c (gas -5, i.e. fully context-sensitive;
// both map to --context entry-state). Two-formal recursion f(x, y) that
// decrements both until x reaches 0 and returns y. Each level enters with
// a distinct (x, y) pair, so entry-state creates one exact context per
// level and the result is the singleton 0. Depth scales linearly: f(300,
// 300) takes about 1 s, f(1000, 1000) about 7 s on the same machine and is
// left out to stay clear of the runner's ceiling. --context call-string
// at any depth up to 5 answers UNKNOWN for all three (the collapsed key
// joins the remaining (x, y) pairs).
fun i32 f(i32 x, i32 y) {
  if (x == 0) { return y; }
  i32 r = f(x - 1, y - 1);
  return r;
}
fun main() {
  i32 a = f(8, 8); __voblint_check(a == 0);    // PROVED
  i32 b = f(20, 20); __voblint_check(b == 0);  // PROVED
  i32 c = f(300, 300); __voblint_check(c == 0); // PROVED
}

// Adapted from Goblint tests/regression/79-callstring/10-inf_callstack_cs.c
// (ana.context.callString_length -1, an unbounded call string, which
// behaves like Goblint's full context and maps to --context entry-state).
// o(i) counts i down and writes the global m at every level, so after the
// call m holds the deepest level's write, 0. Entry-state keys each level
// by its entered i, the deepest activation is analyzed with i=[1,1] and
// writes m := 0, and the combine after each call site reads that back.
// Any bounded call string collapses the deep levels instead;
// known-imprecision/01 pins that at depth 5.
global i32 m;
fun i32 o(i32 i) {
  if (0 < i) { i = i - 1; m = i; o(i); }
  return 0;
}
fun main() {
  m = 20;
  o(5);
  __voblint_check(m == 0); // PROVED
  m = 20;
  o(8);
  __voblint_check(m == 0); // PROVED
  m = 20;
  o(25);
  __voblint_check(m == 0);  // PROVED
}

// Adapted from Goblint tests/regression/80-context_gas/12-multiple_function_chain_sens.c
// and 13-multiple_function_chain_ins.c (ana.context.gas_value 10; the
// 13 checks exceed the gas and are UNKNOWN in Goblint, while Goblint's
// default full context, which --context entry-state maps to, proves all of
// them). The chain f -> g -> h with h self-recursive: f(i) = g(i-1) = h(i-2)
// = ... = h(0) = 3 for i >= 2. Entry-state keys every h level by its
// entered i, so each is exact down to h(0), and the deepest chain
// (h(300), 301 levels) takes about 1 s. Under --context none the same
// program is UNKNOWN throughout; known-imprecision/02 names the mechanism.
fun i32 h(i32 i) {
  if (i == 0) { return 3; }
  if (0 < i) { i32 r = h(i - 1); return r; }
  return 13;
}
fun i32 g(i32 i) {
  if (i == 0) { return 2; }
  if (0 < i) { i32 r = h(i - 1); return r; }
  return 12;
}
fun i32 f(i32 i) {
  if (i == 0) { return 1; }
  if (0 < i) { i32 r = g(i - 1); return r; }
  return 11;
}
fun main() {
  i32 a = f(10); __voblint_check(a == 3);  // PROVED
  i32 b = f(8); __voblint_check(b == 3);   // PROVED
  i32 c = h(5); __voblint_check(c == 3);   // PROVED
  i32 d = f(0); __voblint_check(d == 1);   // PROVED
  i32 e = f(1); __voblint_check(e == 2);   // PROVED
  i32 x = g(0); __voblint_check(x == 2);   // PROVED
  i32 y = g(1); __voblint_check(y == 3);   // PROVED
  i32 z = f(11); __voblint_check(z == 3);  // PROVED
  i32 u = g(12); __voblint_check(u == 3);  // PROVED
  i32 v = g(20); __voblint_check(v == 3);  // PROVED
  i32 w = f(20); __voblint_check(w == 3);  // PROVED
  i32 s = h(40); __voblint_check(s == 3);  // PROVED
  i32 t = h(300); __voblint_check(t == 3); // PROVED
  i32 q = f(300); __voblint_check(q == 3);  // PROVED
}

// Adapted from Goblint tests/regression/80-context_gas/07-main_recursion_sens.c
// (ana.context.gas_value 10). Goblint recurses through main itself; VIMP's
// main cannot be called, so the recursion lives in a helper. rec decrements
// the global num_iterat from 11 and recurses while it is positive, then
// returns 5 from the num_iterat == 0 base case, and every level passes 5
// back up. The result is proved in every mode, including --context none:
// the base case's num_iterat == 0 guard selects the `return 5` arm on any
// state containing 0, and the recursive arm only forwards that value.
global i32 num_iterat;
fun i32 rec() {
  if (0 < num_iterat) {
    num_iterat = num_iterat - 1;
    i32 res = rec();
    __voblint_check(res == 5); // PROVED
    return res;
  } else {
    if (num_iterat == 0) { return 5; } else { return 2; }
  }
}
fun main() {
  num_iterat = 11;
  i32 r = rec();
  __voblint_check(r == 5); // PROVED
}

// Ported from Example_Interval_DG_Ctx_Globals_Regression (gcall_entry_first,
// gcall_entry_second, gcall_entry_third, gcall_after_first_return) and
// Example_Interval_DG_EntryState_Result_Regression (gcall_result_bump_first,
// _second, _third, gcall_result_after_first_return). Same program as
// 04-globals/precision/03-global_across_calls_entry_state.vimp, plus checks
// pinning the declared global g at bump's entry in each of its three contexts
// ([5,5], [4,4], [19,19]) and in main after the first return.
//
// A check inside bump is decided per context and the verdicts are joined, so
// "g == 10" alone would be UNKNOWN (PROVED in one context, REFUTED in two).
// "(n == K) == (g == G)" is PROVED only if, in every context, both comparisons
// are decided and agree: n = [K,K] forces g = [G,G], and any other n forces g
// to exclude G. An inexact g anywhere leaves one side at [0,1]. Under
// --context none all three are UNKNOWN.
global i32 g;
fun i32 bump(i32 n) {
  __voblint_check((n == 5) == (g == 10)); // PROVED
  __voblint_check((n == 4) == (g == 15)); // PROVED
  __voblint_check((n == 19) == (g == 19)); // PROVED
  g = g + n;
  return g;
}
fun main() {
  g = 10;
  i32 a = bump(5);
  __voblint_check(g == 15); // PROVED
  i32 b = bump(4);
  __voblint_check(a == 15); // PROVED
  __voblint_check(b == 19); // PROVED
  __voblint_check(g == 19); // PROVED
  i32 c = bump(g);
  __voblint_check(c == 38); // PROVED
  __voblint_check(g == 38); // PROVED
}

// Ported from Example_Interval_DG_Ctx_Factorial_Regression (fact_return_ctx_a,
// _b, _a2, _a1) and Example_Interval_DG_EntryState_Result_Regression
// (fact_result_base_case_live_ctx). Same program as
// 03-procedures/precision/06-recursive_factorial_dead_branch_no_bottom_leak.vimp,
// plus checks pinning each inner activation's returned value.
//
// factorial runs under four entry-state contexts, n = [1,1] .. [4,4]. a == 6 and
// b == 24 pin the [3,3] and [4,4] returns. The three checks after the recursive
// call pin r, the return of the [n-1,n-1] activation, in each caller context: a
// check is joined across contexts, so each is written to be decided and true in
// all of them at once (see 08-global_entry_value_per_context.vimp). The
// base-case check is live only under n = [1,1].
fun i32 factorial(i32 n) {
  __voblint_check(0 < n); // PROVED
  if (n < 2) {
    __voblint_check(n == 1); // PROVED
    return 1;
  } else {
    i32 r = factorial(n - 1);
    __voblint_check(0 < r); // PROVED
    __voblint_check((n == 2) == (r == 1)); // PROVED
    __voblint_check((n == 3) == (r == 2)); // PROVED
    __voblint_check((n == 4) == (r == 6)); // PROVED
    return n * r;
  }
}
fun main() {
  i32 a = factorial(3);
  i32 b = factorial(4);
  __voblint_check(a == 6); // PROVED
  __voblint_check(b == 24); // PROVED
}

// Adapted from Goblint tests/regression/85-narrow_globs/07-ctxt-widen.c
// (ana.context.gas_value 0, i.e. context-insensitive, with
// solvers.td3.narrow-globs enabled, which lets Goblint prove all seven).
// Same program as precision/04-function_chain_self_recursive_tail.vimp;
// every concrete result is 3. Under --context none each procedure has one
// activation shared by all its call sites, so h's entry is seeded by the
// join of every argument reaching it: i=[0,2147483646] (the upper bound
// widened, the lower bound 0 kept). The else edge of i == 0 moves the
// lower bound past 0, so the following (i <= 0) arm is dead, its
// fall-through `return 13` never contributes, and every result is [3,3].
// Voblint needs no counterpart of narrow-globs here because the lower
// bound of the seed survives widening.
fun i32 h(i32 i) {
  if (i == 0) { return 3; }
  if (0 < i) { i32 r = h(i - 1); return r; }
  return 13;
}
fun i32 g(i32 i) {
  if (i == 0) { return 2; }
  if (0 < i) { i32 r = h(i - 1); return r; }
  return 12;
}
fun i32 f(i32 i) {
  if (i == 0) { return 1; }
  if (0 < i) { i32 r = g(i - 1); return r; }
  return 11;
}
fun main() {
  i32 a = f(11); __voblint_check(a == 3);  // PROVED
  i32 b = g(12); __voblint_check(b == 3);  // PROVED
  i32 c = g(20); __voblint_check(c == 3);  // PROVED
  i32 d = f(20); __voblint_check(d == 3);  // PROVED
  i32 e = h(40); __voblint_check(e == 3);  // PROVED
  i32 x = h(300); __voblint_check(x == 3); // PROVED
  i32 y = f(300); __voblint_check(y == 3);  // PROVED
}

// Concretely only f(100, 0) enters the branch, so x = 100 and y = 0 there.
//
// Entry-state contexts separate f(100, 0) from f(0, 100): inside the branch Interval
// alone knows x = 100 and y = 0, so it decides every check without asking Order.
fun f(i32 x, i32 y) {
  i32 z;
  if (y <= x) {
    __voblint_check((y <= x) + 1 == 2); // PROVED
    z = (y <= x);
    x = 0;
    __voblint_check(z == 1); // PROVED
    __voblint_check(y == 1); // REFUTED
  }
}
fun main() {
  f(0, 100);
  f(100, 0);
}

// g is called only from f, and f from two sites in main. A call string of
// length 2 keeps the two activations of g apart ([f-site, main-site]), so
// each returns its own argument; length 1 merges them at f's one call site
// (known-imprecision/05-call_string_depth_one_merges_nested_calls.vimp).
fun i32 g(i32 p) {
  return p;
}
fun i32 f(i32 p) {
  i32 t = g(p);
  return t;
}
fun main() {
  i32 x = f(3);
  i32 y = f(-10);
  __voblint_check(x > 0); // PROVED
  __voblint_check(y < 0); // PROVED
}

// Concretely m == 2 holds for the call f(1) and for f(x) with x = 1, and fails
// for x = 2 and x = 3, so UNKNOWN is the only sound verdict at the check.
//
// Entry-state contexts give f two contexts: {n=[1,1]} from the first call, in
// which m=[2,2] and the check is PROVED, and {n=[1,3]} from the second, in which
// m=[2,6] admits the odd values no run has and the check is UNKNOWN. The node
// verdict joins the two to UNKNOWN. Backs the soundness chain figure of the
// thesis (Chapter 10).
fun i32 f(i32 n) {
  i32 m = 2 * n;
  __voblint_check(m == 2); // UNKNOWN
  return m;
}

fun main() {
  i32 a = f(1);
  i32 x = __voblint_nondet_int();
  if (0 < x) {
    if (x < 4) {
      i32 b = f(x);
    }
  }
}

// The stride loop from Mine's tutorial example 4.10: v starts at 1 and
// steps by 2 while v < 51, so v is exactly 51 on exit.
//
// Congruence holds the stride and nothing else. The loop head joins 1 and
// 3 into 1 (mod 2), v := v + 2 maps that class to itself, and the fixpoint
// is reached in one further step -- no widening needed, which is why the
// domain publishes no warrowing discipline. The exit guard
// contributes nothing: inv_less_congruence is the identity, so (v >= 51)
// leaves the class untouched.
//
// The concrete mechanism losing v == 51 is therefore the lattice, not the
// transfer functions: a residue class carries a residue and a modulus and
// no magnitude, so 1 (mod 2) is the strongest statement available and
// congruence_eqb declines on it. The composite recovers the exact value --
// 16-composite-domain/precision/05-mine_ex410_stride2_congruence.vimp runs
// this same loop under --analysis int, where the interval narrows v to
// [51,52] and the congruence-to-interval reduction rounds that
// class-aligned to [51,51].
fun main() {
  i32 v = 1;
  while (v < 51) {
    v = v + 2;
  }
  __voblint_check(v == 51); // UNKNOWN
}

// The else-branch is reached exactly when n is not 4, so (n != 4) is a
// fixed fact there.
//
// Two mechanisms stack, and only the outer one is a lattice limit. The
// filter first: cong_refine (Congruence_Kind.thy) leaves both sides
// unchanged for a disequality, so the false arm of an equality guard
// learns nothing and n stays top. That is not an unreached case -- the
// complement of a singleton is not a residue class, so there is nothing
// for the false arm to narrow to. The check layer then declines: top
// shares a value with 4, so cong_eq cannot decide n != 4.
//
// This is why the case sits here rather than reading as a fixable gap.
// --analysis interval has the same shape and the same answer; recovering
// it needs a disjunctive or exclusion domain, which no domain here is.
fun main() {
  i32 n = __voblint_nondet_int();
  if (n == 4) {
    __voblint_check(true); // PROVED
  } else {
    __voblint_check(n != 4); // UNKNOWN
  }
}

// a is concretely 6. The context-insensitive run cannot say so.
//
// The concrete mechanism is the shared callee context. Ctx_None gives
// twice one FunctionEntry slot for both call sites, so p is seeded with
// the join of the singletons 3 and 5. That join is the smallest residue
// class containing both, 3 (mod 2); p * 2 carries it to 2 (mod 4); and
// congruence_eqb declines on a non-singleton. Nothing is lost inside the
// callee -- the transfer is exact on the class it was given.
//
// ../precision/07-entry_state_separates_calls.vimp is the same program
// under --context entry-state, where the two seeds stay apart and both
// checks are decided.
fun i32 twice(i32 p) { return p * 2; }
fun main() {
  i32 a = twice(3);
  i32 b = twice(5);
  __voblint_check(a == 6); // UNKNOWN
}

// The default-policy runs of the precision fixtures that use
// --signed-overflow assume_wraparound. Every value is fixed at i32:
// s = 4, a = 12, g = 5, x is even, so x != 3 holds and x == 5 is never
// taken. 6 * n + 1 wraps to every odd i32, so r is odd and r == 4 is never
// taken.
//
// Under the default assume_top, Goblint's congruenceDomain.ml answers top
// for a signed + or * unless no_ov holds, and standalone Congruence has no
// interval to establish it, not even for two singletons (cong_arith_ik).
// So the singleton sum (08), the class returned through a call (05, 07),
// the global stride (06), the even class (13) and its dead branch (03), and
// the remainder's residue (09) are all lost. Only a difference of two
// constants in range survives; ../precision/14 lists what Congruence still
// decides under assume_top. The Int product keeps these classes when its
// interval shows the result fits (27-signed-overflow/precision/04).
global i32 g;
fun i32 triple(i32 p) { return p * 3; }
fun bump() { g = g + 4; }
fun main() {
  i32 s = 2 + 2;
  __voblint_check(s == 4); // UNKNOWN
  i32 a = triple(4);
  __voblint_check(a == 12); // UNKNOWN
  g = 1;
  bump();
  __voblint_check(g == 5); // UNKNOWN
  i32 n = __voblint_nondet_int();
  i32 x = 2 * n;
  __voblint_check(x != 3); // UNKNOWN
  if (x == 5) {
    __voblint_check(false); // REFUTED
  }
  i32 r = (6 * n + 1) % 6;
  if (r == 4) {
    __voblint_check(false); // REFUTED
  }
}

// n is an unconstrained i32 and n * 3 may overflow, but the truth is fixed:
// i32 multiplication wraps modulo 2^32 and 3 is invertible mod 2^32, so
// n * 3 == 12 holds exactly when n == 4. Both checks hold at every store
// reaching them.
//
// The guard refinement inverts only + and - (refine_var in
// Nonrelational_Transfer.thy); a product stops it, so the guard leaves n at
// top whatever the overflow policy, and both checks stay UNKNOWN. Under the
// default assume_top the forward value of n * 3 is top as well.
fun main() {
  i32 n = __voblint_nondet_int();
  if (n * 3 == 12) {
    __voblint_check(n == 4); // UNKNOWN
    __voblint_check(n != 0); // UNKNOWN
  }
}

// The acceptance case for Congruence as a public analysis: a fact no other
// selectable domain here recovers, established by running the arithmetic
// backwards out of a guard.
//
// n is unconstrained, so the forward direction learns nothing. The guard
// n + 1 == 3 is where the domain earns its place: bfilter_congruence
// (Congruence_Backward.thy) intersects the two sides -- top + 1 against the
// singleton 3 -- and then pushes the result back through inv_plus_congruence,
// subtracting the literal 1 to pin n to the single integer 2. Parity also
// inverts +, but it recovers only n's class (even); Congruence is the one
// component whose inverse pins the integer.
//
// Once n is a singleton (modulus 0), congruence_eqb decides equality against
// a literal in both directions, so the positive and the negated check are
// both discharged.
fun main() {
  i32 n = __voblint_nondet_int();
  if (n + 1 == 3) {
    __voblint_check(n == 2); // PROVED
    __voblint_check(n != 5); // PROVED
  } else {
    __voblint_check(true); // PROVED
  }
}

// Reachability from modular information alone: x is 0 (mod 2) for every
// value n takes, 5 is 5 (mod 0), and the two classes are disjoint, so
// intersect_congruence returns bottom and the then-branch is proved dead.
//
// The check layer uses the same disjointness: cong_eq
// (Congruence_Kind.thy) refutes an equality between disjoint classes, so
// 13-disjoint_classes_decide_equality.vimp proves the same kind of claim when
// it appears as a check.
//
// Run under --signed-overflow assume_wraparound: the case tests congruence
// arithmetic modulo 2^32 on signed i32. Under Goblint's default assume_top a
// signed +, - or * that may overflow gives top instead (27-signed-
// overflow/known-imprecision/02).
fun main() {
  i32 n = __voblint_nondet_int();
  i32 x = 2 * n;
  if (x == 5) {
    __voblint_check(false); // NOWARN (unreachable)
  } else {
    __voblint_check(true); // PROVED
  }
}

// The guard x == y meets two classes. x = 4 * n + 1 is 1 (mod 4); 4 divides
// 2^32, so the class survives i32 wraparound. y = 6 * m + 3 does not keep
// 3 (mod 6): 6 * m wraps to every even value, so y is only odd. The meet of
// 1 (mod 4) and 1 (mod 2) narrows y to 1 (mod 4), which excludes y == 3;
// Parity, which keeps only "odd" for both, leaves that check UNKNOWN.
// y == 13 is concretely reachable (n = 3, and 6 * m == 10 has an i32
// solution because 2 divides 10 and 3 is invertible mod 2^31), so
// check(false) there is REFUTED.
//
// Run under --signed-overflow assume_wraparound: the case tests congruence
// arithmetic modulo 2^32 on signed i32. Under Goblint's default assume_top
// both products may overflow, x and y become top, and the meet has nothing
// to narrow.
fun main() {
  i32 n = __voblint_nondet_int();
  i32 m = __voblint_nondet_int();
  i32 x = 4 * n + 1;
  i32 y = 6 * m + 3;
  if (x == y) {
    __voblint_check(y != 3); // PROVED
    if (y == 13) {
      __voblint_check(false); // REFUTED
    }
  } else {
    __voblint_check(true); // PROVED
  }
}

// Congruence through the routed spine's enter and combine edges rather
// than intra-procedural transfer alone. The guard pins n to 4 in the
// caller; enter_congruence_ci_for binds that class to the formal p in a
// fresh frame (locals default to top, so nothing else leaks in);
// return_congruence publishes p * 3 to ret_var; and combine reads it back
// as a, still a singleton.
//
// Context-insensitive by construction: triple has one call site, so
// Ctx_None already gives it an exact entry class. The context-sensitive
// counterpart is 07-entry_state_separates_calls.vimp.
//
// Run under --signed-overflow assume_wraparound: the case is about routing a
// class through enter and combine, and its classes come from signed
// arithmetic, which standalone Congruence answers with top under Goblint's
// default assume_top (27-signed-overflow/known-imprecision/02).
fun i32 triple(i32 p) { return p * 3; }
fun main() {
  i32 n = __voblint_nondet_int();
  if (n == 4) {
    i32 a = triple(n);
    __voblint_check(a == 12); // PROVED
    __voblint_check(a != 11); // PROVED
  } else {
    __voblint_check(true); // PROVED
  }
}

// A declared global carried across a call boundary. cinit_congruence_st
// (Congruence_Exec.thy) starts a global at the single integer 0 and every
// local at top, so the ownership split is visible in the initial state
// itself: g is a Global_Location and survives enter_frame_congruence_for,
// which resets locals to top.
//
// bump's write is read back at the caller through the combine edge, so
// g == 5 is decided on a singleton rather than on a joined class.
//
// Run under --signed-overflow assume_wraparound: the case is about a global
// carried across a call, and its classes come from signed arithmetic, which
// standalone Congruence answers with top under Goblint's default assume_top
// (27-signed-overflow/known-imprecision/02).
global i32 g;
fun bump() { g = g + 4; }
fun main() {
  g = 1;
  bump();
  __voblint_check(g == 5); // PROVED
  __voblint_check(g != 4); // PROVED
}

// The context-sensitive counterpart 05-congruence_across_call.vimp names.
// triple has two call sites carrying different singleton classes. Joined at
// one context, p is the congruence join of 4 and 5 -- gcd(|4-5|) = 1, so
// 1 (mod 1), every integer -- and return_congruence publishes p * 3 as
// 0 (mod 3), which decides neither check: --analysis congruence alone
// answers UNKNOWN twice with a==0 (mod 3), b==0 (mod 3).
//
// Under entry-state contexts the two call sites seed triple separately,
// each with its own singleton, so combine reads back 12 and 15 exactly.
// The entry-state route is the whole content of this case: the same
// program, the same domain, decided only because the contexts stay apart.
//
// Run under --signed-overflow assume_wraparound: the case is about entry-
// state contexts, and its classes come from signed arithmetic, which
// standalone Congruence answers with top under Goblint's default assume_top
// (27-signed-overflow/known-imprecision/02).
fun i32 triple(i32 p) { return p * 3; }
fun main() {
  i32 a = triple(4);
  i32 b = triple(5);
  __voblint_check(a == 12); // PROVED
  __voblint_check(b == 15); // PROVED
}

// Exact integers retain all six comparison results, including negative
// operands and equality boundaries. Congruence previously answered UNKNOWN
// for every ordering query, even when both classes were singletons.
fun main() {
  i32 x = -1;
  i32 y = 0;
  __voblint_check(x < y); // PROVED
  __voblint_check(x <= x); // PROVED
  __voblint_check(y > x); // PROVED
  __voblint_check(x >= x); // PROVED
  __voblint_check(x == x); // PROVED
  __voblint_check(x != y); // PROVED
  __voblint_check(x < x); // REFUTED
  __voblint_check(y <= x); // REFUTED
  __voblint_check(x > x); // REFUTED
  __voblint_check(x >= y); // REFUTED
  __voblint_check(x == y); // REFUTED
  __voblint_check(x != x); // REFUTED
}

// Arithmetic produces the exact singleton 4. Congruence decides both its
// equality and ordering queries; singleton ordering no longer falls back
// to UNKNOWN.
//
// Run under --signed-overflow assume_wraparound: the case is about deciding
// an order on a singleton, and its classes come from signed arithmetic, which
// standalone Congruence answers with top under Goblint's default assume_top
// (27-signed-overflow/known-imprecision/02).
fun main() {
  i32 x = 2 + 2;
  __voblint_check(x == 4); // PROVED
  __voblint_check(x < 9); // PROVED
}

// Over i32, n * 6 wraps to every even value, so the dividend is every odd
// value and the remainder is odd, in [-5,5], but never 4. Congruence
// keeps the dividend odd modulo 2^32 and the remainder odd, and backward
// intersection removes the r == 4 branch. A linear equality on the
// remainder recovers its exact value -5.
//
// Run under --signed-overflow assume_wraparound: the case tests congruence
// arithmetic modulo 2^32 on signed i32. Under Goblint's default assume_top a
// signed +, - or * that may overflow gives top instead (27-signed-
// overflow/known-imprecision/02).
fun main() {
  i32 n = __voblint_nondet_int();
  i32 dividend = n * 6 + 1;
  i32 r = dividend % 6;
  if (r == 4) {
    __voblint_check(false); // NOWARN
  }
  if (r + 5 == 0) {
    __voblint_check(r == -5); // PROVED
    __voblint_check(r < 0); // PROVED
  }
  i32 q = -7 / 3;
  __voblint_check(q == -2); // PROVED
}

// Exact division over i32. 12 * n + 3 is only 3 (mod 4) after wraparound,
// because 12 * n reaches every multiple of 4. The quotients by 3 and -3
// are then no longer 1 (mod 4) and 3 (mod 4), as they are over unbounded
// integers: 7 / 3 == 2 and -5 / -3 == 1, so both guarded branches are
// reachable and their check(0) is REFUTED. A guard on a singleton still pins the quotient.
fun main() {
  i32 n = __voblint_nondet_int();
  i32 positive = (12 * n + 3) / 3;
  i32 negative = (12 * n + 3) / -3;
  if (positive == 2) {
    __voblint_check(0); // REFUTED
  }
  if (negative == 1) {
    __voblint_check(0); // REFUTED
  }
  if (positive == 1) {
    __voblint_check(positive != 0); // PROVED
  }
  if (negative == -1) {
    __voblint_check(negative < 0); // PROVED
  }
}

// Source: Example_Congruence_Backward (inv_plus_congruence_regression,
// inv_minus_congruence_regression, inv_times_congruence_modular_regression,
// inv_times_congruence_incompatible_regression,
// inv_times_congruence_nonsingleton_fallback,
// congruence_intersection_incompatible_regression,
// congruence_false_disequality_refines).
//
// Each guard runs one backward inverse. n + 1 in 2 (mod 4) gives n in
// 1 (mod 4), so n == 3 is dead and n == 5 is live; n - 1 in 2 (mod 4)
// gives 3 (mod 4); n * 2 odd is impossible. 6 * k + 2 wraps to any even
// value over i32, so n * 2 == 6 * k + 2 does not fix n mod 3 and n == 3
// stays live there. Multiplying two non-singleton classes inverts to
// nothing, so x keeps 1 (mod 4) and x == 13 stays live. Even never equals
// odd. The false arm of n + 1 != 3 pins n to 2.
//
// Run under --signed-overflow assume_wraparound: the case tests congruence
// arithmetic modulo 2^32 on signed i32. Under Goblint's default assume_top a
// signed +, - or * that may overflow gives top instead (27-signed-
// overflow/known-imprecision/02).
fun main() {
  i32 n = __voblint_nondet_int();
  i32 k = __voblint_nondet_int();
  if (n + 1 == 4 * k + 2) {
    if (n == 3) {
      __voblint_check(false); // NOWARN
    }
    if (n == 5) {
      __voblint_check(true); // PROVED
    }
  }
  if (n - 1 == 4 * k + 2) {
    if (n == 5) {
      __voblint_check(false); // NOWARN
    }
    if (n == 7) {
      __voblint_check(true); // PROVED
    }
  }
  if (n * 2 == 6 * k + 2) {
    if (n == 3) {
      __voblint_check(false); // REFUTED
    }
    if (n == 4) {
      __voblint_check(true); // PROVED
    }
  }
  if (n * 2 == 2 * k + 1) {
    __voblint_check(false); // NOWARN
  }
  i32 a = __voblint_nondet_int();
  i32 b = __voblint_nondet_int();
  i32 x = 4 * a + 1;
  i32 y = 6 * b + 3;
  if (x * y == n) {
    if (x == 13) {
      __voblint_check(true); // PROVED
    }
  }
  i32 e = 2 * a;
  i32 o = 2 * b + 1;
  if (e == o) {
    __voblint_check(false); // NOWARN
  }
  if (n + 1 != 3) {
    __voblint_check(true); // PROVED
  } else {
    __voblint_check(n == 2); // PROVED
  }
}

// Source: Example_Congruence_Arithmetic (congruence_bottom_top_regression,
// congruence_definite_arithmetic_regression,
// congruence_modular_arithmetic_regression, aval_congruence_regression,
// congruence_exact_division_regression) and Example_Congruence_Backward
// (congruence_division_remainder_regression).
//
// Singletons stay singletons under +, - and *, and anything times 0 is 0.
// x = 4 * a + 1 keeps 1 (mod 4) over i32, since 4 divides 2^32, but
// y = 6 * b + 3 is only odd: 6 * b wraps to any even value. x + y and
// x - y are 0 (mod 2), so their guards on 1 are dead; x * y is only odd,
// so t == 5 is reachable. Remainder and division keep the class: x % 2 is
// odd, and x % 0 and x / 1 are x. 6 * n wraps to any even value, so
// (6 * n) / 3 can be 1 (4 / 3 == 1), and (6 * n + 1) / 3 is top, so
// u == 2 stays live. Division by 0 is 0 under VIMP's totalization.
//
// Run under --signed-overflow assume_wraparound: the case tests congruence
// arithmetic modulo 2^32 on signed i32. Under Goblint's default assume_top a
// signed +, - or * that may overflow gives top instead (27-signed-
// overflow/known-imprecision/02).
fun main() {
  i32 n = __voblint_nondet_int();
  i32 a = __voblint_nondet_int();
  i32 b = __voblint_nondet_int();
  i32 z = n * 0;
  __voblint_check(z == 0); // PROVED
  i32 s1 = -3 + 5;
  __voblint_check(s1 == 2); // PROVED
  i32 s2 = 7 - 10;
  __voblint_check(s2 == -3); // PROVED
  i32 s3 = -3 * 4;
  __voblint_check(s3 == -12); // PROVED
  i32 x = 4 * a + 1;
  i32 y = 6 * b + 3;
  i32 p = x + y;
  if (p == 1) { __voblint_check(false); } // NOWARN
  i32 m = x - y;
  if (m == 1) { __voblint_check(false); } // NOWARN
  i32 t = x * y;
  if (t == 5) { __voblint_check(false); } // REFUTED
  if (t == 9) { __voblint_check(true); } // PROVED
  i32 o = 2 * a + 1;
  i32 e = o + 1;
  if (e == 3) { __voblint_check(false); } // NOWARN
  i32 r1 = -7 % 3;
  __voblint_check(r1 == -1); // PROVED
  i32 r2 = x % 2;
  if (r2 == 0) { __voblint_check(false); } // NOWARN
  i32 d0 = n / 0;
  __voblint_check(d0 == 0); // PROVED
  i32 r0 = x % 0;
  if (r0 == 3) { __voblint_check(false); } // NOWARN
  i32 d1 = x / 1;
  if (d1 == 3) { __voblint_check(false); } // NOWARN
  i32 h = (6 * n) / 3;
  if (h == 1) { __voblint_check(false); } // REFUTED
  i32 u = (6 * n + 1) / 3;
  if (u == 2) { __voblint_check(true); } // PROVED
}

// x is 0 (mod 2) whatever n is, also after i32 wraparound, so x == 3 is
// false at every execution and x != 3 holds. cong_eq (Congruence_Kind.thy)
// answers an equality when both sides are singletons and otherwise checks
// whether the two classes share a value; 0 (mod 2) and the singleton 3 do
// not, so the check is PROVED without a singleton on the left.
//
// Run under --signed-overflow assume_wraparound: the case tests congruence
// arithmetic modulo 2^32 on signed i32. Under Goblint's default assume_top a
// signed +, - or * that may overflow gives top instead (27-signed-
// overflow/known-imprecision/02).
fun main() {
  i32 n = __voblint_nondet_int();
  i32 x = 2 * n;
  __voblint_check(x != 3); // PROVED
}

// What standalone Congruence still decides under the default assume_top.
// Concretely d = -3, r = 1, q = 6, a = 4 and g = 4.
//
// A difference of two constants that lies in range keeps its singleton
// (cong_arith_ik), here 7 - 10 in main and g - 1 in dec, read back through
// the combine edge. A remainder of in-range operands and a quotient by a
// divisor that excludes -1 cannot leave the kind, so they keep their class
// under every policy: the guard pins n to 13, and 13 % 6 and 13 / 2 stay
// singletons, as does 12 / 3 returned from third. The + and * cases that
// assume_top loses are in ../known-imprecision/06.
global i32 g;
fun i32 third(i32 p) { return p / 3; }
fun dec() { g = g - 1; }
fun main() {
  i32 d = 7 - 10;
  __voblint_check(d == -3); // PROVED
  i32 n = __voblint_nondet_int();
  if (n == 13) {
    i32 r = n % 6;
    __voblint_check(r == 1); // PROVED
    i32 q = n / 2;
    __voblint_check(q == 6); // PROVED
  }
  i32 a = third(12);
  __voblint_check(a == 4); // PROVED
  g = 5;
  dec();
  __voblint_check(g == 4); // PROVED
}

// x is 0 (mod 2), which is exactly what the domain reports, and x == 0 is
// genuinely not fixed by the source: n = 0 gives x = 0 and n = 1 gives
// x = 2, so both a satisfying and a violating execution exist. UNKNOWN is
// the only sound answer -- there is no mechanism losing information here.
//
// The companion refutation is what separates this from the imprecision
// cases: (x != 3) next door in ../known-imprecision/01 is concretely
// fixed and still comes back UNKNOWN. Same abstract value for x, different
// reason for the same verdict.
fun main() {
  i32 n = __voblint_nondet_int();
  i32 x = 2 * n;
  __voblint_check(x == 0); // UNKNOWN
}

// The guard relates two unconstrained variables rather than a variable and
// a literal, so it fixes neither: n = 0, m = 1 satisfies the check and
// n = 5, m = 6 violates it, both reaching the same program point. UNKNOWN
// is the only sound answer.
//
// Congruence's backward filter is not weaker than the source here, it is
// non-relational by construction. inv_eq_congruence intersects the two
// sides' classes, and both are top, so the meet is top; inv_plus_congruence
// then subtracts the literal 1 from top and gets top back. The domain
// tracks one class per variable and has nowhere to record m - n = 1.
fun main() {
  i32 n = __voblint_nondet_int();
  i32 m = __voblint_nondet_int();
  if (n + 1 == m) {
    __voblint_check(n == 0); // UNKNOWN
  }
}

// Parity represents literal zero as Even, which also contains nonzero integers.
// Its numeric queries cannot certify that the divisor is exactly zero.
fun main() {
  i32 quotient = 10 / 0; // ARITH: WARN division-by-zero
  i32 remainder = 10 % 0; // ARITH: WARN remainder-by-zero
  i32 safe = 10 / 3; // ARITH: NONE
}

// Definite hazards coexist with VIMP's total division and remainder results.
fun main() {
  i32 divisor = 0;
  i32 quotient = 7 / divisor; // ARITH: ERROR division-by-zero
  i32 remainder = 7 % divisor; // ARITH: ERROR remainder-by-zero
  __voblint_check(quotient == 0); // PROVED
  __voblint_check(remainder == 7); // PROVED
}

// A known nonzero divisor is safe; an unreachable zero divisor is silent.
fun main() {
  i32 divisor = 3;
  i32 quotient = 7 / divisor; // ARITH: NONE
  i32 remainder = 7 % divisor; // ARITH: NONE
  if (0) {
    i32 dead = 7 / 0; // ARITH: NONE
  } else {
    __voblint_check(quotient == 2); // PROVED
  }
}

// Diagnostics inspect both operands of Boolean expressions.
fun main() {
  __voblint_check(0 && 1 / 0); // REFUTED // ARITH: ERROR division-by-zero
  __voblint_check(1 || 1 / 0); // PROVED // ARITH: ERROR division-by-zero
  __voblint_check(1 && 1 / 0); // REFUTED // ARITH: ERROR division-by-zero
  __voblint_check(0 || 1 / 0); // REFUTED // ARITH: ERROR division-by-zero
}

//
// Simplified ADC peripheral:
// each e* value models one channel-enable register bit.
// count_enabled recursively scans the hardware channels.
//
// The number of enabled channels is in [0,4].
// Computing the average therefore has a possible
// division-by-zero when all channels are disabled.

fun i32 count_enabled(i32 i, i32 e0, i32 e1, i32 e2, i32 e3) {
  if (i == 4) {
    return 0;
  }

  i32 enabled = 0;

  if (i == 0) {
    enabled = e0;
  }

  if (i == 1) {
    enabled = e1;
  }

  if (i == 2) {
    enabled = e2;
  }

  if (i == 3) {
    enabled = e3;
  }

  i32 rest = count_enabled(i + 1, e0, e1, e2, e3);
  return enabled + rest;
}

fun main() {
  // Simulated MMIO register bits.
  i32 e0 = __voblint_nondet_int();
  i32 e1 = __voblint_nondet_int();
  i32 e2 = __voblint_nondet_int();
  i32 e3 = __voblint_nondet_int();

  // Simulated ADC accumulation register.
  i32 adc_sum = __voblint_nondet_int();

  if (0 <= e0 && e0 <= 1 &&
      0 <= e1 && e1 <= 1 &&
      0 <= e2 && e2 <= 1 &&
