// Neither analysis alone gets both. Interval bounds x to [10,11] after the
// loop, which proves 10 <= x but admits 11, so --analysis interval enters the
// branch and reports its check REFUTED. Congruence keeps x even, so the guard
// x == 11 leaves it no value and --analysis congruence reports the check DEAD,
// but it has no bounds and leaves 10 <= x UNKNOWN.
//
// Run together, each check is decided by the met answer, so Interval's proves
// the first; and the combined state is unreachable as soon as one active
// analysis's part is, so Congruence's dead branch is dead for both.
//
// Run under --signed-overflow assume_wraparound: the case is about two
// separate analyses cooperating. Congruence runs without the Int product's
// no_ov here, so under Goblint's default assume_top its x + 2 may overflow
// and gives top (27-signed-overflow/known-imprecision/02).
fun main() {
  i32 x = 4;
  while (x < 10) {
    x = x + 2;
  }
  __voblint_check(10 <= x); // PROVED
  if (x == 11) {
    __voblint_check(x == 12); // NOWARN
  }
}

// Concretely the divisor is the literal 2, so x % 2 never divides by zero.
//
// Parity alone represents 2 as Even, which also contains 0, so
// --analysis parity warns about a possible remainder by zero here
// (23-arithmetic-diagnostics/known-imprecision/01-parity_zero.vimp is the same
// limit for a literal 0). Interval evaluates the divisor to [2,2]. Run
// together, the divisor's value is the met answer of both, which excludes 0,
// so no diagnostic is reported.
fun main() {
  i32 x = __voblint_nondet_int();
  i32 r = x % 2; // ARITH: NONE
}

// Concretely z == 1 at the check: both guards hold, so x == y.
//
// Interval alone leaves z = [0,1] (known-imprecision/01-equality_from_two_guards)
// and the order analysis alone tracks no values (known-imprecision/03-order_alone).
// Run together, Interval's assignment asks the combined state for EvalInt (x == y);
// the order analysis holds (x, y) and (y, x) and answers the exact integer 1, so
// Interval assigns [1,1] and proves the check. The same run is pinned in Isabelle
// by coop_demo_needs_both (src/Examples/CLI/Example_Analysis_Dispatch_Regression.thy).
fun main() {
  i32 x = __voblint_nondet_int();
  i32 y = __voblint_nondet_int();
  if (x <= y) {
    if (y <= x) {
      i32 z = (x == y);
      __voblint_check(z == 1); // PROVED
    }
  }
}

// Concretely z == 0 at the check: both guards hold, so x == y and x != y is 0.
//
// Interval alone leaves z = [0,1] (known-imprecision/02-disequality_from_two_guards).
// Run together, the order analysis answers Interval's EvalInt (x != y) with the
// exact integer 0, so Interval assigns [0,0] and proves the check.
fun main() {
  i32 x = __voblint_nondet_int();
  i32 y = __voblint_nondet_int();
  if (x <= y) {
    if (y <= x) {
      i32 z = (x != y);
      __voblint_check(z == 0); // PROVED
    }
  }
}

// A tour of what the analyzer shows inline, with Interval and the order analysis
// run together and every callee keyed by its entry state.
//
// smaller is entered twice, with (3, 7) and (9, 4), so its header and its return
// show one value per context. The call that discards its result still shows what
// the callee returned. The two guards on x and y are where the order analysis
// records x <= y and then y <= x; the assignment w = x is where it learns w's
// place in that order, by answering its own questions about x.
//
// Each check needs a different part of the run:
//   z == 1  neither alone: Interval asks the order analysis for x == y at
//           z = (x == y), gets 1, and assigns [1,1];
//   w == y  the order analysis alone, from the pairs it learned at w = x;
//   u <= v  neither alone, the other way round: at v = 10 and v = 30 the order
//           analysis asks Interval how v compares with u, records u <= v on
//           both branches, and keeps it through the join Interval loses it in;
//   i == 3  Interval alone, by widening the loop and narrowing it back;
//   n == 7  Interval refutes it: the context entered with (3, 7) returns 3;
// Interval proves the last branch unreachable, and it warns at 100 / x because
// nothing bounds x away from 0.
fun i32 smaller(i32 a, i32 b) {
  i32 lo;
  if (a <= b) {
    lo = a;
  } else {
    lo = b;
  }
  return lo;
}

fun main() {
  i32 x = __voblint_nondet_int();
  i32 y = __voblint_nondet_int();
  i32 q = 100 / x; // ARITH: WARN division-by-zero
  i32 n = smaller(3, 7);
  smaller(9, 4);
  if (x <= y) {
    if (y <= x) {
      i32 z = (x == y);
      i32 w = x;
      __voblint_check(z == 1); // PROVED
      __voblint_check(w == y); // PROVED
    }
  }
  i32 c = __voblint_nondet_int();
  i32 u, v;
  if (0 < c) {
    u = 0;
    v = 10;
  } else {
    u = 20;
    v = 30;
  }
  __voblint_check(u <= v); // PROVED
  i32 i = 0;
  while (i < 3) {
    i = i + 1;
  }
  __voblint_check(i == 3); // PROVED
  __voblint_check(n == 7); // REFUTED
  if (i > 5) {
    __voblint_check(i == 0); // NOWARN
  }
}

// Concretely x <= y at the check: each branch assigns x below y.
//
// Interval alone joins x = [0,20] and y = [10,30], which overlap, and the order
// analysis alone answers only comparisons between variables whose order it
// already records. Run together, the order analysis asks at y = 10 and y = 30
// how the new value compares with x; Interval answers x <= y with the exact 1,
// both branches record the pair, and the join keeps it. This is cooperation
// from the numeric analysis to the relational one, the reverse of
// 03-equality_asked_of_order. The same run is pinned in Isabelle by
// order_asks_needs_both (src/Examples/CLI/Example_Order_Asks_Interval.thy).
fun main() {
  i32 c = __voblint_nondet_int();
  i32 x, y;
  if (0 < c) {
    x = 0;
    y = 10;
  } else {
    x = 20;
    y = 30;
  }
  __voblint_check(x <= y); // PROVED
}

// Concretely x <= y at the check: every path that keeps x sets y above its bound.
//
// The bounds come from guards rather than constants. On the first branch the guard
// leaves x <= 5, so at y = 10 Interval answers x <= y with the exact 1; on the second
// x <= 100 and y = 200 give the same answer. The order analysis records the pair on
// every path, and the join keeps it. Interval alone joins x and y into overlapping
// intervals, and the order analysis alone cannot compare x with a constant
// (06-order_asks_interval is the constant-only form).
fun main() {
  i32 c = __voblint_nondet_int();
  i32 x = __voblint_nondet_int();
  i32 y;
  if (0 < c) {
    if (x <= 5) {
      y = 10;
    } else {
      y = 0;
      x = 0;
    }
  } else {
    if (x <= 100) {
      y = 200;
    } else {
      y = 0;
      x = 0;
    }
  }
  __voblint_check(x <= y); // PROVED
}

// The order analysis on its own. Under x < y it records the pair x <= y and
// proves x <= y, which Interval, tracking each variable separately, cannot.
// It does not close pairs under transitivity, so x <= z stays UNKNOWN under
// y <= z, and y = y + 1 forgets every pair with y. A copy w = x records both
// pairs between w and x, so w == x is PROVED. Backs thesis Section 11.4.
fun main() {
  i32 x = __voblint_nondet_int();
  i32 y = __voblint_nondet_int();
  i32 z = __voblint_nondet_int();
  if (x < y) {
    __voblint_check(x <= y); // PROVED
    if (y <= z) {
      __voblint_check(x <= z); // UNKNOWN
    }
    y = y + 1;
    __voblint_check(x <= y); // UNKNOWN
  }
  i32 w = x;
  __voblint_check(w == x); // PROVED
}

// Concretely x <= y after the branches, so z is 1 at the check.
//
// Int alone joins x = [0,20] and y = [10,30], which overlap, so z = (x <= y)
// is only [0,1]. The order analysis alone cannot compare a variable with a
// constant and records nothing. Run together, the queries go both ways: at
// y = 10 and y = 30 the order analysis asks Int how the new value compares
// with x and records x <= y on both branches, and at z = (x <= y) Int asks
// EvalInt (x <= y), which the order analysis answers with the exact 1.
// The assignment to z is what makes Int ask: on the check x <= y itself the
// order analysis would answer alone, as in 06-order_asks_interval.
fun main() {
  i32 c = __voblint_nondet_int();
  i32 x, y;
  if (0 < c) {
    x = 0;
    y = 10;
  } else {
    x = 20;
    y = 30;
  }
  i32 z = (x <= y);
  __voblint_check(z == 1); // PROVED
}

// Concretely only f(100, 0) enters the branch, so x = 100 and y = 0 there.
//
// Without contexts both parameters range over the two calls' values. Interval
// evaluates (y <= x) by asking it, and Order answers 1 from the guard, so the
// first check is proved; Interval alone leaves it open
// (known-imprecision/07-comparison_interval_alone). Interval stored z = 1 when it
// evaluated the assignment through the channel, so the second check survives
// x = 0 removing Order's fact. No answer decides y == 1.
fun f(i32 x, i32 y) {
  i32 z;
  if (y <= x) {
    __voblint_check((y <= x) + 1 == 2); // PROVED
    z = (y <= x);
    x = 0;
    __voblint_check(z == 1); // PROVED
    __voblint_check(y == 1); // UNKNOWN
  }
}
fun main() {
  f(0, 100);
  f(100, 0);
}

// Concretely only f(100, 0) enters the branch, so x = 100 and y = 0 there.
//
// Entry-state contexts separate the two calls, so inside the branch y is exactly 0
// and the last check is refuted. Both analyses run at every entry-state context.
fun f(i32 x, i32 y) {
  i32 z;
  if (y <= x) {
    __voblint_check((y <= x) + 1 == 2); // PROVED
    z = (y <= x);
    x = 0;
    __voblint_check(z == 1); // PROVED
    __voblint_check(y == 1); // REFUTED
  }
}
fun main() {
  f(0, 100);
  f(100, 0);
}

// At u8, 250 + 10 is computed at i32 (260) and converted back to u8, which
// wraps it to 4. The conversion of 260 to u8 is reported as an error,
// although C defines it as wraparound (as in Goblint).
fun main() {
  u8 x;
  x = 250;
  x = x + 10; // ARITH: ERROR conversion-overflow
  __voblint_check(x == 4); // PROVED
}

// The usual arithmetic conversions turn -1 into 4294967295 before it is
// compared with an unsigned 32-bit value, so -1 < 1u is false, as in C.
fun main() {
  i32 x;
  u32 u;
  x = -1;
  u = 1;
  __voblint_check(x < u); // REFUTED // ARITH: ERROR conversion-overflow
}

// u + 1 is an unsigned 32-bit addition and wraps to 0 before the comparison,
// which is computed at 64 bits because the literal does not fit 32 bits.
// Unsigned arithmetic wraps by definition and raises no diagnostic.
fun main() {
  u32 u;
  u = 4294967295;
  __voblint_check(4294967295 < u + 1); // REFUTED // ARITH: NONE
}

// f and g both take a formal n, at u8 and at i64. The same argument 300 wraps
// to 44 for f and passes unchanged to g; each return converts to its
// procedure's return kind. Converting 300 to u8 is reported as an error;
// i64 holds it, and that conversion raises no obligation.
fun u8 f(u8 n) {
  return n;
}
fun i64 g(i64 n) {
  return n;
}
fun main() {
  i32 a;
  i64 b;
  a = f(300); // ARITH: ERROR conversion-overflow
  __voblint_check(a == 44); // PROVED
  b = g(300); // ARITH: NONE
  __voblint_check(b == 300); // PROVED
}

// Signed division truncates toward zero. INT_MIN / -1 overflows, which C
// leaves undefined; here it wraps back to INT_MIN.
//
// Run under --signed-overflow assume_wraparound: the checks pin wrapped
// values. Under the default assume_top a signed result or conversion outside
// its kind gives Interval the kind's top (27-signed-overflow/known-
// imprecision/01).
fun main() {
  i32 x;
  i32 y;
  x = -2147483648;
  y = x / -1; // ARITH: ERROR signed-overflow
  __voblint_check(y == -2147483648); // PROVED
  __voblint_check(-7 / 2 == -3); // PROVED
  __voblint_check(-7 % 2 == -1); // PROVED
}

// A declared local starts at an arbitrary value of its kind, so before the
// program writes it, it is bounded by its kind's range and nothing more.
fun main() {
  u8 x;
  i8 y;
  __voblint_check(x <= 255); // PROVED
  __voblint_check(0 <= x); // PROVED
  __voblint_check(-128 <= y); // PROVED
  __voblint_check(x < 255); // UNKNOWN
}

// The counter is a u8 formal of a recursive procedure; its range bounds every
// activation.
fun u8 count(u8 n) {
  u8 r;
  if (n == 0) {
    return 0;
  }
  r = count(n - 1);
  return r + 1; // ARITH: WARN conversion-overflow
}
fun main() {
  u8 c;
  c = count(3);
  __voblint_check(c <= 255); // PROVED
}

// No verdict annotations: a parse-rejection case. Every variable declares its
// kind, so an assignment to a name that no declaration, formal or global
// introduces is rejected instead of creating a variable.
fun main() {
  x = 10;
  __voblint_check(x == 10);
}

// Globals carry kinds on their declaration line and start at zero, as C's
// static storage does. A call result converts to the destination's kind.
//
// Run under --signed-overflow assume_wraparound: the checks pin wrapped
// values. Under the default assume_top a signed result or conversion outside
// its kind gives Interval the kind's top (27-signed-overflow/known-
// imprecision/01).
global u8 g;
global i16 h;
fun i32 big() {
  return 70000; // ARITH: ERROR conversion-overflow
}
fun main() {
  __voblint_check(g == 0); // PROVED
  h = big();
  __voblint_check(h == 4464); // PROVED
  g = h; // ARITH: ERROR conversion-overflow
  __voblint_check(g == 112); // PROVED
}

// No verdict annotations: a parse-rejection case. A typed program may not write
// a literal outside i64, the widest kind an unsuffixed C decimal literal can
// take; the typed semantics would otherwise wrap it.
fun main() {
  u64 x;
  x = 18446744073709551616;
}

// A local declaration may initialize its variables, as in C. `i8 x = e;` is the
// declaration followed by the assignment `x = e;`, so the value is converted to
// the local's kind like any assigned value; a declarator without an initializer
// starts at an arbitrary value of its kind. One declaration may mix both.
fun main() {
  i8 u = 127, y;
  i8 x = u + 1; // ARITH: ERROR conversion-overflow
  u32 big = -1; // ARITH: ERROR conversion-overflow
  i32 z = u * 2;
  __voblint_check(u == 127); // PROVED
  __voblint_check(x == -128); // PROVED
  __voblint_check(big == 4294967295); // PROVED
  __voblint_check(z == 254); // PROVED
  __voblint_check(y <= 127); // PROVED
  __voblint_check(y == 0); // UNKNOWN
}

// The declarators of one declaration run left to right, as C sequences them,
// so a later initializer reads the value an earlier one stored.
fun main() {
  i32 a = 1, b = a + 2, c = b * 3;
  __voblint_check(a == 1); // PROVED
  __voblint_check(b == 3); // PROVED
  __voblint_check(c == 9); // PROVED
}

// A declaration may follow statements, as in C99. Its declarators run where they
// are written: `y` reads `x` after the increment, and `z` holds an arbitrary i8
// value only from its own declaration on.
fun main() {
  i32 x = 1;
  x = x + 1;
  i32 y = x;
  __voblint_check(y == 2); // PROVED
  y = 5;
  i8 z;
  __voblint_check(z <= 127); // PROVED
  __voblint_check(z == 0); // UNKNOWN
  __voblint_check(y == 5); // PROVED
}

// A declaration in a loop body runs on every iteration. `c` is initialized
// afresh each time, so it is 1 after its increment however often the loop ran.
// `u` has no initializer: every iteration gives it an arbitrary u8 value, which
// over-approximates C's indeterminate value, so `s` is bounded only by u8.
fun main() {
  i32 i = 0;
  i32 s = 0;
  while (i < 3) {
    i32 c = 0;
    c = c + 1;
    __voblint_check(c == 1); // PROVED
    u8 u;
    s = u;
    i32 t = i;
    i = t + 1;
  }
  __voblint_check(i == 3); // PROVED
  __voblint_check(s <= 255); // PROVED
  __voblint_check(s == 0); // UNKNOWN
}

// Braces open a C block scope. A declaration in an inner block may shadow an
// outer local, a formal or a global; the frontend renames it to `x#2`, a name no
// source can write, so each declaration is its own local identity and the outer
// variable is untouched once the block closes. Branch and loop bodies are blocks.
global i32 g;

fun i32 f(i32 a) {
  {
    i8 a = 3;
    __voblint_check(a == 3); // PROVED
  }
  return a;
}

fun main() {
  i32 x = 1000;
  i32 y = x;
  {
    i8 x = 7;
    y = y + x;
    __voblint_check(x == 7); // PROVED
    {
      u8 x = 255;
      __voblint_check(x == 255); // PROVED
    }
    __voblint_check(x == 7); // PROVED
  }
  __voblint_check(x == 1000); // PROVED
  __voblint_check(y == 1007); // PROVED
  g = 4;
  if (y > 0) {
    i8 g = 1;
    __voblint_check(g == 1); // PROVED
  } else {
    u8 g = 2;
  }
  __voblint_check(g == 4); // PROVED
  i32 r;
  r = f(5);
  __voblint_check(r == 5); // PROVED
}

// No verdict annotations: a parse-rejection case. `x` is declared only inside
// the block, so the later use names no declaration in scope, as C rejects it.
fun main() {
  {
    i32 x = 1;
  }
  i32 y = x;
}

// No verdict annotations: a parse-rejection case. Two declarations of `x` in
// one block, as C rejects them.
fun main() {
  i32 x = 1;
  i8 x = 2;
}

// No verdict annotations: a parse-rejection case. In C the inner `x` is in scope
// in its own initializer, so `x + 1` reads the indeterminate inner `x`, not the
// outer one. The frontend rejects that read instead of choosing a value for it.
fun main() {
  i32 x = 1;
  {
    i8 x = x + 1;
  }
}

// Three hazards C classifies differently: converting 128 to i8 is
// implementation-defined, converting -1 to u32 is defined (modulo 2^32), and
// overflowing i32 addition is undefined. The report words the first two
// "signed/unsigned integer overflow in conversion" and the third "signed integer
// overflow in +"; this fixture vocabulary does not split the conversions.
fun main() {
  i8 a = 128; // ARITH: ERROR conversion-overflow
  u32 b = -1; // ARITH: ERROR conversion-overflow
  i32 c = 2147483647 + 1; // ARITH: ERROR signed-overflow
  __voblint_check(b == 4294967295); // PROVED
}

// A call converts each argument to its formal's kind, as an assignment converts
// to its destination: 200 becomes -56 at i8, -1 becomes 4294967295 at u32, and
// a global passed to a narrower formal wraps the same way. A recursive call
// converts at every level, so its formal stays within the formal's kind.
//
// Run under --signed-overflow assume_wraparound: the checks pin wrapped
// values. Under the default assume_top a conversion outside its kind gives
// Interval the kind's top (27-signed-overflow/known-imprecision/01).
global i32 g;
fun i32 narrow(i8 n) {
  return n;
}
fun i64 widen(u32 n) {
  return n;
}
fun i32 down(u8 n, i32 d) {
  i32 r;
  if (d <= 0) {
    return n;
  }
  r = down(n + 255, d - 1); // ARITH: WARN conversion-overflow
  return r;
}
fun main() {
  i32 a;
  i64 b;
  i32 c;
  a = narrow(200); // ARITH: ERROR conversion-overflow
  __voblint_check(a == -56); // PROVED
  b = widen(-1); // ARITH: ERROR conversion-overflow
  __voblint_check(b == 4294967295); // PROVED
  g = 300;
  a = narrow(g); // ARITH: ERROR conversion-overflow
  __voblint_check(a == 44); // PROVED
  c = down(1, 2);
  __voblint_check(0 <= c); // PROVED
  __voblint_check(c <= 255); // PROVED
}

// A local without an initializer starts at an arbitrary value of its kind on
// every activation. The first call leaves x at 5; the second call does not see
// that value, and neither call sees the zero a call entry writes.
fun i32 f(i32 k) {
  i8 x;
  __voblint_check(x <= 127); // PROVED
  __voblint_check(x >= -128); // PROVED
  __voblint_check(x == 0); // UNKNOWN
  __voblint_check(x == 5); // UNKNOWN
  x = 5;
  return x + k;
}
fun main() {
  i32 a;
  i32 b;
  a = f(1);
  b = f(2);
  __voblint_check(a == 6); // PROVED
  __voblint_check(b == 7); // PROVED
}

// Every activation of a recursive procedure has its own locals, each starting
// at an arbitrary value of its kind. A callee's writes to its own `a` do not
// change the caller's `a`.
fun i32 r(i32 d) {
  u8 a;
  i16 b;
  i32 t;
  __voblint_check(a <= 255); // PROVED
  __voblint_check(0 <= a); // PROVED
  __voblint_check(b <= 32767); // PROVED
  __voblint_check(-32768 <= b); // PROVED
  __voblint_check(a == 0); // UNKNOWN
  a = 7;
  if (d > 0) {
    t = r(d - 1);
  }
  __voblint_check(a == 7); // PROVED
  return a;
}
fun main() {
  i32 v;
  v = r(2);
  __voblint_check(v == 7); // PROVED
}

// An initializer replaces the arbitrary starting value on every activation, so
// both calls see exactly the initialized value.
fun i32 f() {
  i8 x = 3;
  __voblint_check(x == 3); // PROVED
  return x;
}
fun main() {
  i32 a;
  a = f();
  __voblint_check(a == 3); // PROVED
  a = f();
  __voblint_check(a == 3); // PROVED
}

// A library min or max result is converted to its destination's kind like any
// written value. Its obligation is about the result, not the arguments: max(300, 1)
// is 300, which u8 cannot hold, while min(300, 1) is 1, which it can. A result into
// a kind that holds both arguments' kinds raises no obligation.
fun main() {
  i32 x;
  i32 y;
  u8 g;
  u8 h;
  u8 m;
  i64 w;
  g = max(300, 1); // ARITH: ERROR conversion-overflow
  h = min(300, 1); // ARITH: NONE
  m = max(x, 1); // ARITH: WARN conversion-overflow
  w = min(x, y); // ARITH: NONE
  __voblint_check(g == 44); // PROVED
  __voblint_check(h == 1); // PROVED
}

// A call may initialize a declaration, as in C: `u8 b = inc(255);` is the
// call with b as its destination, so the result converts to b's kind. As
// for any call with a destination, the diagnostic for that conversion sits on
// the callee's return. A library call initializes the same way.
fun u16 inc(u16 n) {
  return n + 1; // ARITH: ERROR conversion-overflow
}
fun main() {
  u16 a = inc(255); // ARITH: NONE
  u8 b = inc(255); // ARITH: NONE
  u8 c = max(a, 7); // ARITH: ERROR conversion-overflow
  __voblint_check(a == 256); // PROVED
  __voblint_check(b == 0); // PROVED
  __voblint_check(c == 0); // PROVED
}

// The parser folds a leading minus into a literal and types it by magnitude, so
// -9223372036854775808 is one i64 literal holding -2^63. C reads the same text as
// unary minus applied to 9223372036854775808, a constant no standard signed type
// can hold (C11 6.4.4.1p5-6); VIMP deliberately accepts it. Its value is exact at
// i64, and converting it to i32 wraps to 0 (-2^63 is a multiple of 2^32), which the
// analyzer reports as a definite conversion error.
fun main() {
  i64 x = -9223372036854775808;
  __voblint_check(x < 0);  // PROVED
  __voblint_check(x == -9223372036854775807 - 1);  // PROVED
  i32 y = -9223372036854775808;  // ARITH: ERROR conversion-overflow
  __voblint_check(y == 0);  // PROVED
}

// min and max compare their arguments at the usual arithmetic conversion of the
// two, as the C macro (a) < (b) ? (a) : (b) does. With a at u32, b = -1 converts
// to 4294967295 first, so min(a, b) is 4294967295 and max(c, d) is 4294967295,
// not -1 and 1; i64 destinations keep the difference visible. Both conversions
// of -1 to u32 are definite. u8 and i8 arguments are promoted to i32, where -1
// stays -1; storing it to a u8 wraps to 255.
fun main() {
  u32 a = 4294967295;
  i32 b = -1;
  i32 c = -1;
  u32 d = 1;
  u8 p = 200;
  i8 q = -1;
  i64 m;
  i64 h;
  i32 r;
  u8 n;
  m = min(a, b); // ARITH: ERROR conversion-overflow
  h = max(c, d); // ARITH: ERROR conversion-overflow
  r = min(p, q); // ARITH: NONE
  n = min(p, q); // ARITH: ERROR conversion-overflow
  __voblint_check(m == 4294967295); // PROVED
  __voblint_check(h == 4294967295); // PROVED
  __voblint_check(r == -1); // PROVED
  __voblint_check(n == 255); // PROVED
}

// u8 and i8 arguments of min and max are promoted to i32, and the i32 result is
// converted back to the destination. The promotion changes no value, so the
// result still fits a destination of the arguments' own kind, which a domain
// without magnitudes, such as Sign, can only learn from the arguments' kinds.
fun main() {
  u8 a;
  u8 b;
  u8 m;
  i8 c;
  i8 d;
  i8 n;
  m = min(a, b); // ARITH: NONE
  n = max(c, d); // ARITH: NONE
}

// Concretely b, d and f are INT_MIN, INT_MAX and 0: the semantics wraps.
// Under the default assume_top (Goblint's sem.int.signed_overflow) a signed
// result outside i32 gives Interval the kind's top, so no check is decided.
// This is the policy, not a lattice limit: ../precision/01 proves all three
// under assume_wraparound.
fun main() {
  i32 a = 2147483647;
  i32 b = a + 1; // ARITH: ERROR signed-overflow
  __voblint_check(b == -2147483648); // UNKNOWN
  i32 c = -2147483648;
  i32 d = c - 1; // ARITH: ERROR signed-overflow
  __voblint_check(d == 2147483647); // UNKNOWN
  i32 e = 65536;
  i32 f = e * e; // ARITH: ERROR signed-overflow
  __voblint_check(f == 0); // UNKNOWN
}

// Concretely b, d and f are INT_MIN, INT_MAX and 0. Under the default
// assume_top, Goblint's congruenceDomain.ml answers top for a signed + or *
// unless no_ov holds, which standalone Congruence cannot establish, and for a
// difference of constants that leaves the range. So no check is decided;
// ../precision/02 proves all three under assume_wraparound.
fun main() {
  i32 a = 2147483647;
  i32 b = a + 1; // ARITH: WARN signed-overflow
  __voblint_check(b == -2147483648); // UNKNOWN
  i32 c = -2147483648;
  i32 d = c - 1; // ARITH: WARN signed-overflow
  __voblint_check(d == 2147483647); // UNKNOWN
  i32 e = 65536;
  i32 f = e * e; // ARITH: WARN signed-overflow
  __voblint_check(f == 0); // UNKNOWN
}

// Concretely b, d and f are INT_MIN, INT_MAX and 0. Under the default
// assume_top the interval of each result leaves i32, so no_ov fails and both
// components give the kind's top. ../precision/03 proves all three under
// assume_wraparound; ../precision/04 shows the Int product keeping a class
// when the interval proves that the result fits.
fun main() {
  i32 a = 2147483647;
  i32 b = a + 1; // ARITH: ERROR signed-overflow
  __voblint_check(b == -2147483648); // UNKNOWN
  i32 c = -2147483648;
  i32 d = c - 1; // ARITH: ERROR signed-overflow
  __voblint_check(d == 2147483647); // UNKNOWN
  i32 e = 65536;
  i32 f = e * e; // ARITH: ERROR signed-overflow
  __voblint_check(f == 0); // UNKNOWN
}

// Signed overflow diagnostics, decided from the interval of each operation's
// mathematical result. An ERROR holds at every store reaching the operation;
// a WARN is a possible overflow; an unannotated operation provably fits.
//
// The same program as ../precision/05-diagnostics_wraparound.vimp under the default
// assume_top. The obligations and their meaning do not change with the policy;
// the policy changes only what the domain keeps of a wrapped result. b = a + 1
// still overflows at every reaching store, but its value is now the kind's
// top, so the check on b is UNKNOWN and the nested product h = (a + 1) * 2 is only
// a possible overflow.
fun i32 inc(i32 n) {
  return n + 1; // ARITH: WARN signed-overflow
}
fun main() {
  i32 a; i32 b; i32 c; i32 d; i32 e; i32 f; i32 g; i32 h; i32 m; i32 x; i32 y;
  a = 2147483647;
  b = a + 1; // ARITH: ERROR signed-overflow
  h = (a + 1) * 2; // ARITH: ERROR signed-overflow; WARN signed-overflow
  __voblint_check(b == -2147483648); // UNKNOWN
  c = a - 1;
  d = -a;
  m = -2147483648;
  e = -m; // ARITH: ERROR signed-overflow
  f = m / -1; // ARITH: ERROR signed-overflow
  g = m % -1; // ARITH: ERROR signed-overflow
  x = __voblint_nondet_int();
  if (x < 1000 + x * 2) { // ARITH: WARN signed-overflow; WARN signed-overflow
    y = 1;
  }
  y = inc(x);
  if (x < 1000) {
    if (x > -1000) {
      y = inc(x * 1000);
    }
  }
}

// Conversion diagnostics. Every conversion whose source kind does not widen into
// its target raises an obligation that the converted value fits the target: an
// explicit cast, an assigned value, an argument, a returned value converted to
// the kind of the procedure's result, and a call's result converted to the
// caller's destination. The last is decided where the callee returns. An ERROR
// holds at every store reaching the conversion; a WARN is a possible overflow.
//
// The same program as ../precision/06-conversions_wraparound.vimp under the
// default assume_top: the same obligations and verdicts, since every operand
// value is the same. What changes is the value after a conversion to a signed
// kind that may overflow, which is now the kind's top: c == 44 is UNKNOWN. A
// conversion to an unsigned kind wraps under both policies, so b == 0 is
// still proved.
fun u8 to_byte(i32 n) {
  return n; // ARITH: WARN conversion-overflow
}
fun i32 id(i32 n) {
  return n; // ARITH: ERROR conversion-overflow
}
fun i8 small(i8 n) {
  return n;
}
fun main() {
  i8 c; u8 b; i32 x; i32 y; i64 w; u16 h;
  x = 300;
  c = (i8) x; // ARITH: ERROR conversion-overflow
  __voblint_check(c == 44); // UNKNOWN
  b = x; // ARITH: ERROR conversion-overflow
  b = 255;
  b = 256; // ARITH: ERROR conversion-overflow
  __voblint_check(b == 0); // PROVED
  w = x;
  h = to_byte(7);
  b = to_byte(300);
  c = id(x);
  c = small(x); // ARITH: ERROR conversion-overflow
  y = __voblint_nondet_int();
  b = y % 256; // ARITH: WARN conversion-overflow
  if (y >= 0) {
    if (y < 256) {
      b = y;
    }
  }
}

// INT_MAX + 1, INT_MIN - 1 and 2^16 * 2^16 overflow i32 and wrap to INT_MIN,
// INT_MAX and 0. Under assume_wraparound Interval wraps each singleton result
// as the semantics does, so every check is proved. The assume_top twin is
// ../known-imprecision/01-interval_assume_top.vimp.
fun main() {
  i32 a = 2147483647;
  i32 b = a + 1; // ARITH: ERROR signed-overflow
  __voblint_check(b == -2147483648); // PROVED
  i32 c = -2147483648;
  i32 d = c - 1; // ARITH: ERROR signed-overflow
  __voblint_check(d == 2147483647); // PROVED
  i32 e = 65536;
  i32 f = e * e; // ARITH: ERROR signed-overflow
  __voblint_check(f == 0); // PROVED
}

// The overflowing operations of 01-interval_wraparound.vimp under
// Congruence: a constant result wraps to the constant the semantics computes
// (handle_overflow), so every check is proved. The assume_top twin is
// ../known-imprecision/02-congruence_assume_top.vimp.
//
// Each operation overflows at every store reaching it, and Interval and Int
// report ERROR there (01-interval_wraparound.vimp). Congruence reports only
// WARN: an overflow obligation is decided on the interval component of the
// operands' answers (Run_Report.thy), and Congruence, like Sign, bounds no
// magnitude, so even its singleton a leaves that interval unbounded. A
// literal operand is still its own exact interval, but every operation here
// has a variable operand.
fun main() {
  i32 a = 2147483647;
  i32 b = a + 1; // ARITH: WARN signed-overflow
  __voblint_check(b == -2147483648); // PROVED
  i32 c = -2147483648;
  i32 d = c - 1; // ARITH: WARN signed-overflow
  __voblint_check(d == 2147483647); // PROVED
  i32 e = 65536;
  i32 f = e * e; // ARITH: WARN signed-overflow
  __voblint_check(f == 0); // PROVED
}

// The overflowing operations of 01-interval_wraparound.vimp under the Int
// product: both components wrap, so every check is proved. The assume_top
// twin is ../known-imprecision/03-int_assume_top.vimp.
fun main() {
  i32 a = 2147483647;
  i32 b = a + 1; // ARITH: ERROR signed-overflow
  __voblint_check(b == -2147483648); // PROVED
  i32 c = -2147483648;
  i32 d = c - 1; // ARITH: ERROR signed-overflow
  __voblint_check(d == 2147483647); // PROVED
  i32 e = 65536;
  i32 f = e * e; // ARITH: ERROR signed-overflow
  __voblint_check(f == 0); // PROVED
}

// Under the default assume_top the Int product still keeps a congruence
// across a signed * and + when its interval proves that the result fits:
// Goblint's no_ov, passed from the interval to the congruence. The guard
// bounds n to [0,10], so x = 4 * n + 1 lies in [1,41] and the congruence keeps
// 1 (mod 4). That excludes 3, which the interval [1,41] alone cannot.
// Without the bound, y = 4 * m + 1 may overflow, the congruence goes to top
// under assume_top, and y != 3 is not decided, although it holds: y is
// 1 (mod 4) also after wraparound, since 4 divides 2^32. That last check is
// a known imprecision of assume_top, kept beside the bounded case it
// contrasts with.
fun main() {
  i32 n = __voblint_nondet_int();
  if (0 <= n && n <= 10) {
    i32 x = 4 * n + 1;
    __voblint_check(x != 3); // PROVED
    __voblint_check(x % 4 == 1); // PROVED
  }
  i32 m = __voblint_nondet_int();
  i32 y = 4 * m + 1; // ARITH: WARN signed-overflow; WARN signed-overflow
  __voblint_check(y != 3); // UNKNOWN
}

// Signed overflow diagnostics, decided from the interval of each operation's
// mathematical result. An ERROR holds at every store reaching the operation;
// a WARN is a possible overflow; an unannotated operation provably fits.
//
// b = a + 1 overflows on the one value a holds, and the run still knows the
// wrapped result exactly: the check pins b == INT_MIN. The twin under the
// default assume_top is ../known-imprecision/04-diagnostics_assume_top.vimp: the same obligations,
// with the nested product h = (a + 1) * 2 only a possible overflow there.
fun i32 inc(i32 n) {
  return n + 1; // ARITH: WARN signed-overflow
}
fun main() {
  i32 a; i32 b; i32 c; i32 d; i32 e; i32 f; i32 g; i32 h; i32 m; i32 x; i32 y;
  a = 2147483647;
  b = a + 1; // ARITH: ERROR signed-overflow
  h = (a + 1) * 2; // ARITH: ERROR signed-overflow; ERROR signed-overflow
  __voblint_check(b == -2147483648); // PROVED
  c = a - 1;
  d = -a;
  m = -2147483648;
  e = -m; // ARITH: ERROR signed-overflow
  f = m / -1; // ARITH: ERROR signed-overflow
  g = m % -1; // ARITH: ERROR signed-overflow
  x = __voblint_nondet_int();
  if (x < 1000 + x * 2) { // ARITH: WARN signed-overflow; WARN signed-overflow
    y = 1;
  }
  y = inc(x);
  if (x < 1000) {
    if (x > -1000) {
      y = inc(x * 1000);
    }
  }
}

// Conversion diagnostics. Every conversion whose source kind does not widen into
// its target raises an obligation that the converted value fits the target: an
// explicit cast, an assigned value, an argument, a returned value converted to
// the kind of the procedure's result, and a call's result converted to the
// caller's destination. The last is decided where the callee returns. An ERROR
// holds at every store reaching the conversion; a WARN is a possible overflow.
//
// As Goblint does, Voblint reports conversions to unsigned kinds too, although C
// defines them as wraparound; a conversion to a signed kind is
// implementation-defined in C. The value after a reported conversion is the
// wrapped one, and the run knows it exactly here: c == 44 and b == 0 are proved.
fun u8 to_byte(i32 n) {
  return n; // ARITH: WARN conversion-overflow
}
fun i32 id(i32 n) {
  return n; // ARITH: ERROR conversion-overflow
}
fun i8 small(i8 n) {
  return n;
}
fun main() {
  i8 c; u8 b; i32 x; i32 y; i64 w; u16 h;
  x = 300;
  c = (i8) x; // ARITH: ERROR conversion-overflow
  __voblint_check(c == 44); // PROVED
  b = x; // ARITH: ERROR conversion-overflow
  b = 255;
  b = 256; // ARITH: ERROR conversion-overflow
  __voblint_check(b == 0); // PROVED
  w = x;
  h = to_byte(7);
  b = to_byte(300);
  c = id(x);
  c = small(x); // ARITH: ERROR conversion-overflow
  y = __voblint_nondet_int();
  b = y % 256; // ARITH: WARN conversion-overflow
  if (y >= 0) {
    if (y < 256) {
      b = y;
    }
  }
}

// A signed remainder raises the obligation that its truncated quotient fits the
// kind: C leaves a % b undefined when a / b does not fit (6.5.5p6). m % -1 for
// m == INT_MIN computes 0, but its quotient 2147483648 does not fit i32: an
// ERROR. A negative remainder is ordinary, and a divisor or dividend that rules
// out the pair (INT_MIN, -1) leaves the quotient in range. Unsigned remainders
// wrap by definition and raise no such obligation.
fun main() {
  i32 m; i32 n; i32 r; i32 x; i32 y; i32 q; u32 a; u32 b;
  m = -2147483648;
  r = m % -1; // ARITH: ERROR signed-overflow
  __voblint_check(r == 0); // PROVED
  n = -7 % 2;
  __voblint_check(n == -1); // PROVED
  x = __voblint_nondet_int();
  y = __voblint_nondet_int();
  q = x % 3;
  if (y > 1) {
    q = x % y;
  }
  if (x > -2147483647) {
    q = x % y; // ARITH: WARN remainder-by-zero
  }
  q = x % y; // ARITH: WARN remainder-by-zero; WARN signed-overflow
  a = b % 7;
}

// An overflow obligation tests the interval of the unwrapped result, built from
// the operands' intervals. Sign answers no magnitude for x, but a reaching store
// holds a value of x's kind in x, so x's interval is i32's range. Then x % 2 and
// x / 2 have a quotient in i32 and raise no warning, although a sign has no
// finite end. With an unknown divisor y, x % y and x / y may divide INT_MIN by
// -1, and x + 1 may exceed INT_MAX, so those still warn.
fun main() {
  i32 x; i32 y; i32 q;
  x = __voblint_nondet_int();
  y = __voblint_nondet_int();
  q = x % 2; // ARITH: NONE
  q = x / 2; // ARITH: NONE
  q = x % y; // ARITH: WARN remainder-by-zero; WARN signed-overflow
  q = x / y; // ARITH: WARN division-by-zero; WARN signed-overflow
  q = x + 1; // ARITH: WARN signed-overflow
}

// An overflow obligation tests the interval of the unwrapped result, built from
// the operands' intervals. Congruence answers no magnitude for x, but a reaching store
// holds a value of x's kind in x, so x's interval is i32's range. Then x % 2 and
// x / 2 have a quotient in i32 and raise no warning, although a residue class has no
// finite end. With an unknown divisor y, x % y and x / y may divide INT_MIN by
// -1, and x + 1 may exceed INT_MAX, so those still warn.
fun main() {
  i32 x; i32 y; i32 q;
  x = __voblint_nondet_int();
  y = __voblint_nondet_int();
  q = x % 2; // ARITH: NONE
  q = x / 2; // ARITH: NONE
  q = x % y; // ARITH: WARN remainder-by-zero; WARN signed-overflow
  q = x / y; // ARITH: WARN division-by-zero; WARN signed-overflow
  q = x + 1; // ARITH: WARN signed-overflow
}

// Vanilla with Sign. Over the integers the sum of two negatives is negative, so
// a sign domain proves z < 0 (Monniaux, ETAPS 2024, rule of signs). At i32 the sum
// of two negative values can wrap to a nonnegative one, and a sign bounds no
// magnitude, so Sign gives z the kind top although z = -15 in every run.
fun main() {
  i32 x = -5;
  i32 y = -10;
  i32 z = x + y;
  __voblint_check(z < 0);  // UNKNOWN
}

// Coffee (Monniaux, ETAPS 2024): y = |x|, and y >= 1 implies x != 0. The check holds
// in every run, also at x = -2^31, where -x wraps to -2^31 and y >= 1 fails. Proving
// it needs the relation between x and y on each path; a non-relational interval
// keeps x unconstrained at the check.
fun main() {
  i32 x;
  i32 y = 0;
  if (x >= 0) {
    y = x;
  } else {
    y = -x;
  }
  if (y >= 1) {
    __voblint_check(x != 0);  // UNKNOWN
  }
}

// The bounded variant from the same tutorial: x in [-1000, 2000], y = |x| in
// [0, 2000]. The test y >= 1 refines y to [1, 2000] but leaves x at [-1000, 2000],
// since an interval holds no relation between x and y, so x != 0 stays open
// although it holds in every run.
fun main() {
  i32 x;
  i32 y = 0;
  if (-1000 <= x && x <= 2000) {
    if (x < 0) {
      y = -x;
    } else {
      y = x;
    }
    if (y >= 1) {
      __voblint_check(x != 0);  // UNKNOWN
    }
  }
}

// Blackcurrant (Monniaux, ETAPS 2024): the same counter, incremented only when a
// nondeterministic test holds. i stays in [0, 9] in every run, but the path that
// skips the increment is a self-loop at the loop head, so the next-iteration
// operator never shrinks the widened value and narrowing does not help. Policy
// iteration finds [0, 9]; Voblint has no policy iteration.
fun main() {
  i32 i = 0;
  i32 c;
  while (1) {
    c = __voblint_nondet_int();
    if (c) {
      i = i + 1;
      if (i >= 10) {
        i = 0;
      }
    }
    __voblint_check(i <= 9);  // UNKNOWN
  }
}

// Another example from the same tutorial: the counter resets on i == 10, so i stays
// in [0, 9], but an equality test cuts no interval bound, widening reaches the i32
// limit and narrowing does not recover it. Guided static analysis, which analyses
// growing subgraphs, finds [0, 9]; Voblint does not.
fun main() {
  i32 i = 0;
  while (1) {
    i = i + 1;
    if (i == 10) {
      i = 0;
    }
    __voblint_check(i <= 9);  // UNKNOWN
  }
}

// Optimal only among inductive invariants (Monniaux, ETAPS 2024): i takes 6, 4, 2,
// 0, so i > 0 holds whenever the body starts. Its abstraction + is not inductive,
// because i - 2 of a positive value may be anything, so Sign reaches every sign at
// the loop head.
fun main() {
  i32 i = 6;
  i = i - 2;
  while (i != 0) {
    __voblint_check(i > 0);  // UNKNOWN
    i = i - 2;
  }
}

// Vanilla (Monniaux, "Flavors of abstract interpretation", ETAPS 2024): x and y are
// negative constants, so z = x + y = -15 and z < 0 holds. Interval tracks the
// constants exactly and proves it.
fun main() {
  i32 x = -5;
  i32 y = -10;
  i32 z = x + y;
  __voblint_check(z < 0);  // PROVED
}

// Fudge (Monniaux, ETAPS 2024): the loop head widens i to the i32 limit, and
// narrowing through the exit test recovers i = 10 after the loop.
fun main() {
  i32 i = 0;
  while (i < 10) {
    i = i + 1;
  }
  __voblint_check(i == 10);  // PROVED
}

// Narrowing works (Monniaux, ETAPS 2024): i counts up and resets at 10, so i <= 9
// holds after the reset. Widening sends the upper bound to the i32 limit, where
// i + 1 may overflow, which also loses the lower bound; narrowing brings the upper
// bound back to 9, so the check is proved over i = [-2147483646, 9] rather than
// the [0, 9] the unbounded analysis of the tutorial finds.
fun main() {
  i32 i = 0;
  while (1) {
    i = i + 1;
    if (i >= 10) {
      i = 0;
    }
    __voblint_check(i <= 9);  // PROVED
  }
}
